INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('2308', '台達電子工業 _DELTA ELECTRONICS INC.', '資安產品測試工程師 (Security Product Test Engineer)_產品資安新事業發展部(台北)', '台北市內湖區', '2026-09-10', 'https://www.104.com.tw/job/908wy', '104', '加入我們，打造下一代企業級資安防護！ 本職位專注於將 AI 技術與傳統資安攻防結合後進行資安產品測試。作為團隊的成員，您將負責進行資安產品測試，同時可進行軟體產品與資安工具測試、提供相關測試文件，並利用 AI 工具優化現有流程或產品測試方法，同時研究產品會面臨的CVE漏洞資訊並建議防護方法。 我們正在尋找對技術探索充滿熱誠、具備實戰攻防經驗，且能將 AI 應用於日常資安任務的人才。您將協助團隊挖掘', NULL, NULL, NULL);
