INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('2454', '聯發科', '2027 Campus_Multimedia Platform Engineer', '新竹市', '2026-09-10', 'https://www.104.com.tw/job/8tg7l', '104', '我們在找這樣的你！ (每位應徵者最多可投遞 5 個職缺，提供研發替代役名額) 如果你是 2027 年應屆畢業之碩士或博士生，具備電機、電子、資訊、資工、資管、電信、通訊、電控等相關背景，並對半導體技術、AI 運算、無線通訊、智慧裝置、多媒體平台等領域充滿熱忱，歡迎加入聯發科技，與我們一起打造影響全球的創新科技。 我們期待你樂於學習、勇於挑戰，能主動思考並提出想法，重視團隊合作，面對困難保持好奇心與', NULL, NULL, NULL);
