INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('2882', '國泰金控_國泰金融控股', '資深數據工程師 Senior Data Engineer -集團徵才-數據科技 (數數發中心, DDT)_I00015418', '台北市信義區', '2026-09-08', 'https://www.104.com.tw/job/87vsz', '104', '[主要任務] 1. 設計、開發和維護金融業數據架構及服務，包括數據湖、數據pipeline及數據服務系統等。 2. 進行需求分析和系統設計，確定最佳的軟體架構和解決方案。 3. 實現高品質的代碼，並進行單元測試和整合測試，確保軟體的穩定性和可靠性。 4. 使用CI/CD（持續整合/持續部署）工具和流程，自動化測試、版本控制和部署流程，以提高效率和品質。 5. 與數據科學家、商業分析師和產品團隊合作', NULL, NULL, NULL);
