INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('2303', 'Phison Electronics Corp_群聯電子', 'AI演算法工程師/AI Algorithm Engineer(竹南/台北)', '苗栗縣竹南鎮', '2026-09-09', 'https://www.104.com.tw/job/8t4pq', '104', '負責分析AI算法在實際系統架構運行時的效能瓶頸。 AI 應用成為近幾年的主流，軟體服務的效能依賴於幾個重點：系統架構設計、演算法的實作、硬體規格。 過去為了提升協作開發效率，計算機領域主要朝著抽象化的方式，降低各層互相的耦合性。 然而，這其中的權衡奠基在過去硬體隨著摩爾定律效能快速的成長，在大型系統中往往能藉由過剩的硬體效能彌補抽象化造成的損失。 然而，AI 時代迎來模型參數和運算需求指數成長的情', NULL, NULL, NULL);
