INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('2949', '欣新網', '【台中】Key Account_電商業務副理_熟AI Agent應用／熟電商平台操作優先', '台中市西區', '2026-08-31', 'https://www.104.com.tw/job/8j5mj', '104', '【國際品牌合作／策略執行／彈性環境】 你是不是常常逛Momo、蝦皮購物、PChome時，會想著—— 「這個活動怎麼設計出來的？」 或者，你曾經想過：「如果這個品牌讓我來經營，我一定可以讓它賣得更好。」  我們正在找的，像你這樣，對品牌經營與電商銷售充滿洞察與好奇心的人！  【關於欣新網】 我們是欣新網，一家協助國際品牌拓展電商市場的服務商。 與我們合作的品牌涵蓋美妝、保健、家居等多元領域，客戶包含', NULL, NULL, NULL);
