INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('7757', '金色三麥', '金色三麥酒窖店-【調酒吧檯師 Bartender】#月薪5萬#週排休2日_Dream Plaza', '台北市信義區', '2026-09-08', 'https://www.104.com.tw/job/8r1ab', '104', '金色三麥酒窖店【調酒吧檯師 Bartender】Dream Plaza 如果你愛Show，熱愛與客人大方互動，喜歡與客人成為朋友，享受每一杯飲料調製的成就!	 如果你在尋找屬於你發揮吧檯專業的舞台， 金色三麥就是最適合你的地方。	 我們需要有經驗，有想法，尋找對餐酒有熱忱的夥伴，歡迎你的加入!	 	 1.  提供調製傳統與創新調酒 2.  提供顧客酒水等相關服務，瞭解其口味喜好並提供個性化的調酒建', 50000, 9999999, NULL);
