INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('3703', '欣陸', '品質部規章管理組_高級/資深工程師', '台北市大安區', '2026-09-07', 'https://www.104.com.tw/job/8m1df', '104', '1.	協助集團規章管理制度之規劃設計與導入落實 (25%) -依照集團規章程序管理制度之發展與規劃，透過相關管理措施與組織資源，協助制度之實施落實，並確保規章程序與制度管理的有效性。 -協助推動流程管理應用相關主題之宣導與交流活動，確保程序制訂相關人員之職能與技術，並提升全體同仁對規章程序的理解、重視、及遵循。 -參與探討與規章程序管理與落實相關之先進科技與技術應用，協助中長期發展與建置藍圖之規劃', NULL, NULL, NULL);
