INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('6214', '精誠', 'AI工程師-V35C', '台中市西屯區', '2026-09-07', 'https://www.104.com.tw/job/8zxvb', '104', '1. 負責 AI / LLM 應用系統開發，包含聊天機器人、知識庫問答、文件分析等應用。  2. 設計與實作 RAG（Retrieval-Augmented Generation）架構，提升模型回應品質。  3. 進行 Prompt Engineering 設計與優化，改善模型表現與使用體驗。  4. 整合 LLM 與既有系統（Web / API / 資料庫），實現 AI 功能落地應用。  5.', 50000, 100000, NULL);
