INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('5403', '中菲', '資深DBA系統工程師（專業服務部D組）', '台北市內湖區', '2026-08-20', 'https://www.104.com.tw/job/8obyl', '104', '1.負責專案客戶之SQL Server 服務器的日常運維管理與升級、上版和架構設計、性能優化、故障處理與災難恢復、數據備份恢復等。 2.提升資料庫運維工作系統化、自動化、規範化程度。 3.協助資料庫同異質移轉及相關工具使用 4.定期健檢維護服務作業，並產出報告與建議。 5.整理資料庫運維案例、經驗分享、故障處理文檔。', 50000, 70000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('3714', '富采光電 (原為晶元光電及隆達電子)', '資料工程師 (竹科)', '新竹市', '2026-08-27', 'https://www.104.com.tw/job/7csd2', '104', '【資訊中心】 在富采，資訊中心涵蓋智慧製造、AI 應用、網頁與系統開發、ERP與資訊安全等關鍵領域， 驅動企業數位轉型，為富采建構智慧化、數據化與可擴展的營運發展。  【工作內容】 1.設計並維護數據治理平台、資料商城。 2.設計、開發和維護可擴展的數據分析模型。 3. APC 製程參數控制 AI 模型開發。 4.使用者介面前端 Web GUI 開發。 5. 主管交辦事項  【其他技能】 1. 熟', NULL, NULL, NULL);
