INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('5403', '中菲', '系統分析師（專案軟體事業部）', '台北市內湖區', '2026-08-20', 'https://www.104.com.tw/job/86oa0', '104', '我們正在尋找熱愛團隊合作、對於解決問題充滿熱情的軟體工程師加入我們的團隊。 主要產品為提供金融產業資訊系統、大型連鎖商店系統。   本工作主要內容為客戶訪談、系統分析、核心程式撰寫、產品測試、客戶支援。', NULL, NULL, NULL);
