INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_宜格立有限公司', '宜格立有限公司', '寵物通路開發經理｜兼職顧問', '台南市南區', '2026-09-10', 'https://www.104.com.tw/job/95rh1', '104', '我們是一間專營歐美母嬰與寵物用品進口代理的品牌公司，目前正積極拓展台灣寵物用品市場。我們正在尋找一位熟悉台灣寵物產業、具有實際通路開發能力與產業人脈的合作夥伴。  如果你目前或曾經在寵物產業工作，熟悉寵物店、寵物連鎖、選品店、沙龍或動物醫院，並希望利用既有經驗發展額外收入，非常適合與我們聊聊。  【主要工作內容】  1. 寵物用品通路開發：開發全台寵物用品實體通路 2. 新品牌與商品提案：品牌商品', 36000, 9999999, NULL);
