INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('3443', '黑柑創意工作室', '業務', '高雄市鹽埕區', '2026-08-28', 'https://www.104.com.tw/job/95bre', '104', '1. 發掘新商機： 在學校及補教業中尋找並開拓新的業務機會。 2. 跟進與轉化： 跟進公司提供的潛在客戶線索，將業務諮詢轉化為確定的銷售業績。 3. 建立客戶關係： 與學校校長、科主任（Panel Heads）及關鍵決策者建立並維護緊密的合作關係。 4. 專業方案演示： 專業地展示我們的解決方案，以滿足每所學校的特定需求。  履歷可直接電郵至 admin@hagencreative.tw', NULL, NULL, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_軒和數位整合行銷企業社', '軒和數位整合行銷企業社', '兼職/保底直播主播（在家經營）', '台北市信義區', '2026-09-04', 'https://www.104.com.tw/job/8nhej', '104', '【歡迎有活力、有熱忱、想嘗試網路直播的你！】 工作內容： 1.主播可自行安排時段在家或任何場所，透過手機APP開啟直播與觀眾進行良好互動及節目表演。 2.提升網路人氣，吸引高收入觀眾。 3.直播時能與粉絲進行良好互動關係。  4.表演節目、活動之事前規劃與演練。  保底企劃： 1.公司提供月薪3-10萬等多項保底企劃 於面試時提供最合適的方案給你。 2.提供各項競賽活動獎金。 3.薪水=保底+額外', 30000, 80000, NULL);
