INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_阿蒂瑪有限公司', '阿蒂瑪有限公司', 'AI agency 海外商務開發經理（Creator Economy / 數位資產收購）', '台北市內湖區', '2026-09-04', 'https://www.104.com.tw/job/95khe', '104', '工作內容： 於英文社群（論壇、X、Telegram、Discord）開發海外創作者經濟領域的收購標的與合作夥伴 管理標的 pipeline：月新增 20+ 有效接觸、3~5 個進入初步盡調 執行首輪盡調：營收驗證、集中度分析、產出一頁式標的報告 對接行業工具商與交易平台，建立轉介網絡  要求： 1.英文書寫母語級（工作 100% 靠英文文字溝通） 2.2 年以上 BD 經驗，以下背景擇一：iGam', 55000, 120000, NULL);
