INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_心家娛樂有限公司', '心家娛樂有限公司', '17LIVE官方直播主(無經驗可.在家上班.高獎金)', '台中市東區', '2026-09-09', 'https://www.104.com.tw/job/7adkw', '104', '【心家娛樂 - 17LIVE 官方直播主熱烈招募中！】  我們是心家娛樂有限公司，自2017年成立以來，作為17LIVE內部的專業經紀公司，致力於發掘和培養有潛力的直播人才。 如果你對直播充滿熱情，無論有無經驗，這裡將是你實現夢想的舞台！  不論你是： - 無經驗，但願意學習成長的新手。 - 有經驗，卻遇到瓶頸的資深主播。  只要你肯學，我們提供專業經紀人一對一輔導，幫助你突破自我，打造個人品牌，', 30000, 80000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_科碼新媒體股份有限公司', '科碼新媒體股份有限公司', '[科碼]博物館數位互動設備維護人員', '台北市大同區', '2026-09-04', 'https://www.104.com.tw/job/8wdtg', '104', '工作內容（依專案安排）  	•	數位互動裝置之例行巡檢、設備保養  	•	互動程式、觸控螢幕、感測器等設備的故障排除與簡易修復  	•	投影機、伺服器、播放器等硬體設備之定期檢修、除塵與狀況記錄  	•	展場突發狀況支援（如畫面異常、裝置無反應、連線異常等）  	•	基本線路、網路設備檢查（HDMI、電源線、路由器、交換器）  	•	協助展覽期間之維運、開閉館設備啟動與關機程序  	•	完成維護紀', 30000, 9999999, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_貳樓餐飲集團 SECOND FLOOR', '貳樓餐飲集團 SECOND FLOOR CAFE(北區)_貳樓餐飲股份有限公司', '【貳樓餐飲集團】人資處招募專員/資深專員', '台北市北投區', '2026-09-06', 'https://www.104.com.tw/job/7b2ma', '104', '- 依據公司各單位人才需求招募相應人才。 - 執行各招募管道，包括產學合作、外籍人才、派遣人力等的持續穩定流入。 - 透過系統工具(招募、排班、人事等系統)，協助門店人力合理配置，與人才全週期發展。 - 按門店區域劃分，執行下列業務：     人員資料建檔維護(含勞健保及團險加退保)。     人事異動(包含到職、離職、資遣)等相關業務處理。     協助員工排班/考勤作業。     協助處理員工', 35000, 9999999, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_亞映娛樂事業有限公司', '亞映娛樂事業有限公司', '業配廣告業務', '台北市內湖區', '2026-08-13', 'https://www.104.com.tw/job/94tky', '104', '【工作內容】 我們正在尋找熱愛 Podcast 聲音經濟、具備商務開發能力的「業配業務夥伴」！你將負責為我們的 Podcast 頻道媒合合適的品牌廠商，協助品牌透過聲音將價值傳遞給聽眾。  品牌廠商開發：主動拓展潛在贊助商／廣告主（B2B 開發），精準媒合適合頻道的品牌與商品。  提案與客製化規劃：根據廠商需求與頻道風格，規劃業配方案、撰寫提案簡報並進行商務洽談。  專案執行與跨部門溝通：擔任品牌', 10000, 100000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_雍興實業股份有限公司', '雍興實業股份有限公司', '派駐公股銀行長期月薪制勞務員(台北巿內湖區)', '台北市內湖區', '2026-09-04', 'https://www.104.com.tw/job/92b86', '104', '協助內勤文書相關工作 熟電腦office軟體操作 認真.負責.積極 備汽車駕照 上班時間:8:50-17:10 週休二日 享三節奬金.年節禮盒 勞健團保及退休金提撥', 32750, 32750, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_Group.G Co., Ltd._伽馬', 'Group.G Co., Ltd._伽馬實業有限公司', '社群企劃 專案', '台北市大安區', '2026-07-16', 'https://www.104.com.tw/job/7r5oq', '104', '工作內容  【社群行銷企劃與執行能力】    1.具備獨立規劃社群專案之行銷波段與媒體宣傳波段的能力。  2.社群之文章撰寫、製圖或與設計部合作產出社群貼文。  3. 短影音腳本規劃撰寫能力。  4.可掌握專案進度，並控制成本。  5.具備溝通協調能力，可與行銷內部與其他部門夥伴，共同完成專案。  6.社群維運、留言回覆等。', 30000, 9999999, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_VISION Consultant_亮惟', 'VISION Consultant_亮惟有限公司', 'AI供應鏈產業專家', '台北市大安區', '2026-07-09', 'https://www.104.com.tw/job/8v1fn', '104', '我們是一家專注於「專業顧問 × 知識共創 × 產業洞察」的顧問平台，致力於讓行業專家的經驗與知識被更多金融企業決策者與學習者看見,提供投資者更多的專業見解。  目前我們正在邀請具備AI供應鏈產業經驗與專業洞察的專家加入「亮惟顧問合作計畫」  行業類別: 新能源 / 燃料電池 / 功率半導體 工業電子 / 電氣設備 / 被動元件 半導體 / 光電 / 網通晶片 軟體 / 雲端 / 企業應用', 10000, 30000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_美商愛思捷科技有限公司台灣分公司', '美商愛思捷科技有限公司台灣分公司', '簡體中文語言學專家 Simplified Chinese Linguistics Expert', '台北市信義區', '2026-09-08', 'https://www.104.com.tw/job/8dxxn', '104', '1. 協助標註簡體中文語言資料 2. 處理並修復簡體中文文法錯誤 3. 評估、更新和分享簡體中文語言資料標註準則 4. 監控資料的取得和整理 5. 與客戶一起開發和審查數據 6. 評估和審查自然語言資料 7. 創建和評估自然語言模型 8. 創建和審查人工智慧回應信息  此職務為派遣性質，專案為期約6個月至1年期(實際需視客戶需求仍有延長或縮短的可能性)，可台灣境內遠端工作。', NULL, NULL, 'remote');
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('1216', '統一佳佳股份有限公司', 'BEING spa櫃檯人員(台南湖美館)', '台南市中西區', '2026-08-03', 'https://www.104.com.tw/job/8sac2', '104', '1.顧客接待諮詢  2.電話接聽.預約安排  3.會員經營服務  4.帳務管理.產品盤點   5.喜愛接觸人群.個性積極親切  6.具美容或飯店櫃檯服務經驗者佳  7.具備基本外語會話能力尤佳', 30000, 40000, NULL);
