INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_花甲樂股份有限公司', '花甲樂股份有限公司', '花甲樂日照中心/護理師(工作地點:高雄大寮)', '高雄市大寮區', '2026-09-11', 'https://www.104.com.tw/job/8w88k', '104', '1.日照個案收托及管理評估 2.個案用藥、疾病管理 3.緊急/意外傷害應變處理 4.個案健康管理及定期護理需求評估，擬訂照護計畫並執行相關紀錄 5.執行健康促進活動及家屬衛教、護理諮詢 6.指導照顧服務員長者照顧與技巧 7.感染控制與預防 8.協助機構評鑑相關事宜 9.行政會議參與及其他主管交辦日照相關事項  工作地點:高雄大寮，依人力需求及應徵者意願協調安排', 38000, 48000, NULL);
