INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_藝珂人事顧問股份有限公司', '藝珂人事顧問股份有限公司', '桃園以北【全球前500大外商】水處理技術服務工程師環工 #固定日班 #年度調薪 #年假16天_ITS_842', '台北市士林區', '2026-09-11', 'https://www.104.com.tw/job/91bp1', '104', '☆歡迎喜歡彈性外勤工作模式的夥伴! (大部分時間都獨立遠端在外~) ☆固定日班，週休六日~不輪班!    ※您將加入我們水處理應用的優秀團隊。運用您的熱情與專業技術開發和管理技術專案以解決客戶問題，誠摯歡迎化工、化學、材料、電機、機械等相關科系人才，通過一連串的服務實踐，一同與團隊達成超越客戶期望的目標。  【公司經營理念】 作為全球專業商用領域清潔、消毒、食品安全、預防感染、水和能源領域的開拓者', 43000, 50000, NULL);
