INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_岳凌科技有限公司', '岳凌科技有限公司', '語音互動主播｜無需露臉｜自由排班', '新竹市', '2026-09-09', 'https://www.104.com.tw/job/945e7', '104', '「在家兼職｜純語音聊天主播｜免露臉・無經驗可」  ▼ 職務說明 喜歡聊天，就有機會把你的聲音變成一份收入！  不用露臉、不用準備專業直播設備，也不要求唱歌或特殊才藝。 工作主要透過語音直播平台與用戶聊天互動、分享生活，建立自己的聲音特色與固定聽眾。  完全沒有直播經驗也可以！ 我們提供完整新人培訓，從平台操作、聊天技巧、直播互動到用戶經營，都有專人一步步帶領，讓新手也能安心開始。  ▼ 工作內容', 500, 9999999, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_森品食品有限公司', '森品食品有限公司', '高雄食品業務（遠端工作/無底薪高獎金）(兼職)', '高雄市左營區', '2026-09-03', 'https://www.104.com.tw/job/8xieo', '104', '【森品冷凍肉品】業務合作夥伴｜稀有部位 x 省工調理｜無底薪・高抽成・免囤貨  森品專注於提供具差異化的優質肉品與調理食品。從市面少見的稀有部位（如：雞牡蠣、雞松坂），到協助餐廳解決缺工痛點的省工調理包（舒肥雞胸、醃漬肉品、預炸類肉品），我們的產品線具備極強的市場競爭力。  隨著業務擴張，我們正在尋找熟悉餐飲生態、或擁有團購人脈的你，一起將這些「能幫老闆賺錢、省人工」的好食材推廣出去！  歡迎加入', 1000, 5000, 'remote');
