INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_富康活力連鎖藥局_富康活力醫藥股份有限公', '富康活力連鎖藥局_富康活力醫藥股份有限公司', '【高雄三民】藥局門市人員｜有藥局經驗薪資可談｜高薪、穩定', '高雄市三民區', '2026-09-08', 'https://www.104.com.tw/job/8zd8b', '104', '富康活力藥局為穩定發展中的連鎖藥局品牌，致力於提供專業、溫暖且值得信賴的健康服務。我們重視每一位同仁的專業發展與工作安心感，提供完整制度與培訓，讓夥伴能在穩定的環境中持續成長。  【工作內容】 1. 門市顧客服務與健康諮詢 2. 商品介紹與銷售（保健食品、醫療用品等） 3. 商品陳列與庫存管理 4. 協助門市營運與基本行政作業 5. 協助維持門市環境整潔與服務品質  【工作時間】 • 採早、晚班輪', 34000, 44000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_創星娛樂有限公司', '創星娛樂有限公司', '遊戲/實況直播主(TP)', '台北市中山區', '2026-09-09', 'https://www.104.com.tw/job/8vcrf', '104', '歡迎成為自媒體產業的一員，想瞭解現在最夯的直播平台及增加額外收入或者提高知名度、提升粉絲人數，創星娛樂給您最完整的資訊。   此為遠端工作，無地區限制，可在家工作、正職或者兼職皆可。  **遊戲/實況主播工作內容如下**   平台名稱 : 17Live  1.聚集網路人氣，吸引目標觀眾，與觀眾有良好的互動。  2.配合宣傳直播平台、公司經營之活動。  3.透過APP直播平台與觀眾互動，培養粉絲 。', 1750, 95250, 'remote');
