INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_財團法人臺南市台日文化友好交流基金會', '財團法人臺南市台日文化友好交流基金會', '日本政經產業研究暨企劃專員（Japan Industry Research & Project Specialist）', '台南市東區', '2026-09-11', 'https://www.104.com.tw/job/949uy', '104', '日本政經產業研究暨企劃專員（Japan Industry Research & Project Specialist）  工作內容  我們致力推動台日產業合作、地方交流及政策研究，期待尋找一位對日本產業發展充滿熱情的人才，共同參與台日合作專案。  工作內容包括：  一、日本產業研究  蒐集與分析日本產業政策、市場趨勢及企業資訊 研究日本政府補助、產業政策及地方創生計畫 撰寫產業分析、研究報告及簡報', 36000, 9999999, NULL);
