INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_銳譯翻譯_銳譯企業社', '銳譯翻譯_銳譯企業社', '韓中字幕審校人員 (全遠端)', '台北市內湖區', '2026-09-10', 'https://www.104.com.tw/job/95fr2', '104', '銳譯翻譯成立的宗旨是提供兼具語言品質與在地文化敏感度的專業翻譯服務，協助客戶跨越語言與市場的界線。我們的團隊橫跨台灣、日本、韓國與歐美地區，服務範圍包括：  網漫與漫畫在地化 遊戲及影片字幕翻譯 文件與企業專案翻譯 多語種專案管理與在地化顧問服務  我們相信「語言是文化的橋樑」，致力於讓每一個譯稿都能兼具精確度與流暢度，傳達出原作的真實意圖與情感。  招募職稱  韓中字幕審校暨翻譯人員（Korea', 34000, 9999999, NULL);
