INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_藝珂人事顧問股份有限公司', '藝珂人事顧問股份有限公司', '【美商500大服務企業｜環境衛生與永續管理專家】儲備區域業務 TMIT #餐飲飯店經驗 #售後服務客戶經營 #外勤自主安排#具駕駛經驗者_ITS_837', '台中市西屯區', '2026-09-08', 'https://www.104.com.tw/job/95nvr', '104', '【公司介紹】 國際知名 Fortune 500 美商，專注於食品安全、環境衛生及永續管理服務，透過專業技術與顧問服務協助企業提升營運品質與顧客體驗。客戶橫跨餐飲、零售、飯店及工業市場，提供多元發展機會與完善人才培育機制。 此職位結合 設備技術服務＋既有客戶經營，以客戶現場服務為主，並非大量陌生開發型業務。  【職務內容】 • 維護及發展指定區域之餐飲、飯店及商業客戶關係，成為客戶值得信賴的衛生與食', NULL, NULL, NULL);
