INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_全球人事顧問股份有限公司', '全球人事顧問股份有限公司', '【銀行儲備理專】均46K起/無經驗可培訓/ 台北 MT', '台北市萬華區', '2026-09-11', 'https://www.104.com.tw/job/94ids', '104', '★知名金控集團『儲備理專培育計畫』招募中★ 完整理財培育藍圖，打造全方位財富管理顧問 掌握現有客戶名單與資源，專注客戶經營與服務 從金融新手躍升財富管理專家，挑戰高收入職涯發展!!  ★【職務優勢】★ 完整理財專員培訓計畫，透過「1對1導師培訓＋輔導考照＋業務實習實戰」，快速學會客戶經營、資產配置與金融產品顧問能力 有機會服務高資產客戶，學習成功心法，洞察致富思維，邁向財富之路  ★【計畫優勢】★', 46000, 9999999, NULL);
