INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_杏恩醫療儀器有限公司', '杏恩醫療儀器有限公司', '徵【桃園、中壢業務人員】#尋找陌生開發能力強的夥伴', '桃園市中壢區', '2026-09-04', 'https://www.104.com.tw/job/8q7gm', '104', '業務工作：  @醫院、醫美、泌尿科、家醫科、牙科及各科系診所市場開發。  @醫療設備銷售。  @醫療耗材銷售。  @既有客戶服務。    我們主要販售醫療產品：雷射儀器，手術房設備，消毒設備，AI醫療，消耗性醫療用品。    公司網站簡介：https://www.shinn.com.tw/    我們有非常好的產品與資源，若你對於自己的銷售能力很有自信，歡迎加入我們。    1.個人獎金  2.收', 36000, 100000, NULL);
