INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_長順織襪有限公司', '長順織襪有限公司', '早中晚班直播主', '台中市北屯區', '2026-09-10', 'https://www.104.com.tw/job/8yxzh', '104', '工作內容 1.臉書/抖音/蝦皮直播商品。 2.負責介紹直播商品。 3.直播後台小幫手。 4.負責商品穿搭介紹。 *需有直播經驗', 250, 280, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_台灣本事股份有限公司', '台灣本事股份有限公司', '酒類銷售業務人員(遠距上班/台中大里區)', '台中市大里區', '2026-09-06', 'https://www.104.com.tw/job/916ma', '104', '本事選酒致力推廣日本酒文化與創新酒體驗，代理多家日本知名酒造，並開發自有品牌「六茶+美人」，延伸研發至六大茶系風味梅酒款，展現台灣茶與酒文化的創意融合。  1. 彈性工作制度：不需進公司打卡，可遠端辦公，我們重視自律與信任的夥伴文化。 2. 會議協作機制：每週三次線上會議，檢討業績並共同制定市場策略。 3. 進度管理：每日線上回報工作進度，確保團隊溝通與效率。 4. 客戶拜訪與開發：需實體拜訪客戶', 42000, 58000, 'remote');
