INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_戰馬國際娛樂股份有限公司', '戰馬國際娛樂股份有限公司', '語音聲播(不露臉+保底方案)/兼職正職皆可/在家工作/遠端', '高雄市新興區', '2026-09-03', 'https://www.104.com.tw/job/81ez0', '104', '自媒體時代利用在家閒暇時間直播就能賺錢 現代社會直播非常普遍,但有一種語音直播您知道嗎?  「語音直播有別於視訊直播，不需化妝、不需準備燈光設備、不需露臉，回歸到最純粹的方式用「聲音」做直播 一天只需1-2小時,時間完全自由安排。兼職/正職都可以 用多餘的閒暇時間額外多一筆收入 只要你有企圖心，我們都肯教你，不讓你成為直播孤兒，活潑開朗、愛唱歌、有企圖心、有夢想、都歡迎來了解看看   主要工作內容', 1000, 100000, 'remote');
