INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_優士國際資安股份有限公司', '優士國際資安股份有限公司', 'ISO 27001資安顧問(北北基桃)', '桃園市桃園區', '2026-09-06', 'https://www.104.com.tw/job/8zp13', '104', '負責協助客戶建立或維護資訊安全管理制度，透過提供專業的資通安全諮詢建議或解決方案給客戶來滿足資訊系統的安全性和合規性要求、精進資訊安全管理制度，以及客戶所有可能面臨的資安需求諮詢工作：    1.輔導客戶導入與維護基礎資通安全或個人資料保護相關國際標準，並取得證書。       (如：ISO 27001、ISO 27701...等)    2.提供客戶專業資通安全相關諮詢。(如：合規相關議題、實務', 30000, 80000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('5312', '寶島光學科技股份有限公司', '【台中嶺東路】驗光人員/門市銷售人員 (寶島眼鏡-台中)', '台中市南屯區', '2026-08-27', 'https://www.104.com.tw/job/929td', '104', '◆【工作內容】 專業驗光、配鏡加工，及鏡框鏡片調整、清潔等服務 眼鏡商品介紹、銷售等販售管理 顧客售後服務與關懷 維護門市場所與商品之清潔、美觀 各項門市行政作業與系統操作 各式商品包裝、上架陳列  ◆【需求條件】 驗光人員：視光本科系畢業                    具備驗光師、驗光生證照                     ※具同業經驗者尤佳 (薪資另議)  門市銷售人員：對眼鏡', 37000, 70000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_森品食品有限公司', '森品食品有限公司', '彰化食品業務（遠端工作/無底薪高獎金）(兼職)', '彰化縣彰化市', '2026-09-03', 'https://www.104.com.tw/job/8xk2z', '104', '【森品冷凍肉品】業務合作夥伴｜稀有部位 x 省工調理｜無底薪・高抽成・免囤貨  森品專注於提供具差異化的優質肉品與調理食品。從市面少見的稀有部位（如：雞牡蠣、雞松坂），到協助餐廳解決缺工痛點的省工調理包（舒肥雞胸、醃漬肉品、預炸類肉品），我們的產品線具備極強的市場競爭力。  隨著業務擴張，我們正在尋找熟悉餐飲生態、或擁有團購人脈的你，一起將這些「能幫老闆賺錢、省人工」的好食材推廣出去！  歡迎加入', 1000, 5000, 'remote');
