INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('3443', '普拉瑞斯創意整合有限公司', '海外數位行銷(SEO行銷企劃專員)【普拉共好圈聯盟商】', '台中市西屯區', '2026-09-03', 'https://www.104.com.tw/job/88imm', '104', '我們正在尋找具備國際市場SEO經驗的數位行銷合作夥伴，協助企業客戶提升全球搜尋能見度與網站流量成效。 若您熟悉Google SEO操作，並對B2B產業的海外市場拓展有興趣，歡迎加入我們的專案合作。  【工作內容】 1. 規劃與執行Google SEO搜尋引擎優化策略，包含關鍵字研究、SEO內容規劃及網站排名優化。 2. 進行產業市場分析與競爭者SEO分析，提出可行的優化策略與執行建議。 3. 追蹤', NULL, NULL, NULL);
