INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_摩絡人工智慧股份有限公司', '摩絡人工智慧股份有限公司', '前線部署工程師 Forward Deployed Engineer（FDE）', '新竹市', '2026-07-29', 'https://www.104.com.tw/job/936bj', '104', 'Forward Deployed Engineer(FDE)是橫跨工程實作與客戶現場的關鍵角色。你將帶著我們的 AI Agent 平台走進客戶產線,將工廠分散的多源營運資料,轉化為可實際支援決策的系統。對客戶而言,你是最了解其問題的技術夥伴;對內部而言,你是產品團隊在前線的洞察來源。  【工作內容】 - 需求定義與問題收斂：深入客戶現場,與使用者、IT等團隊合作,釐清產線痛點與營運目標,將營運需求', 900000, 9999999, NULL);
