INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_英屬開曼群島商慧康生活科技股份有限公司台', '英屬開曼群島商慧康生活科技股份有限公司台灣分公司', '數位醫療業務代表_高屏地區(遠端)｜Sales Representative _ Kaohsiung and Pingtung Region (Remote)', '高雄市苓雅區', '2026-09-08', 'https://www.104.com.tw/job/7xiwj', '104', '▋▍About Us｜關於我們（醫療 X 科技）  用數據與科技，重新定義慢性病照護。  慧康生技（Health2Sync）旗下產品「智抗糖 App」是亞洲最大的慢性病管理平台。我們致力於建構一個連結病患、醫療單位與藥廠的「數位醫療生態圈」。  不同於傳統單一藥品或醫材銷售，我們的業務團隊是「診所升級與自費營收的成長夥伴」。我們提供結合「SaaS 雲端照護系統」、「頂尖亞培 CGM 血糖管理療程」', NULL, NULL, NULL);
