INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_鴻翔國際電通股份有限公司', '鴻翔國際電通股份有限公司', '高屏區 駐區業務代表', '高雄市三民區', '2026-09-10', 'https://www.104.com.tw/job/68fbt', '104', '1. 開發潛在客戶，拓展市場，達成業績目標。 2. 定期拜訪經銷客戶，維繫穩定客戶關係。 3. 負責國內業務接洽及訂單處理。 4. 產品報價與推廣。 5. 蒐集客戶情報，並負責客訴問題之處理。', 40000, 100000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_富康活力連鎖藥局_富康活力醫藥股份有限公', '富康活力連鎖藥局_富康活力醫藥股份有限公司', '【高雄鳳山】藥局門市人員｜有藥局經驗薪資可談｜高薪、穩定', '高雄市鳳山區', '2026-09-08', 'https://www.104.com.tw/job/8zd88', '104', '富康活力藥局為穩定發展中的連鎖藥局品牌，致力於提供專業、溫暖且值得信賴的健康服務。我們重視每一位同仁的專業發展與工作安心感，提供完整制度與培訓，讓夥伴能在穩定的環境中持續成長。  【工作內容】 1. 門市顧客服務與健康諮詢 2. 商品介紹與銷售（保健食品、醫療用品等） 3. 商品陳列與庫存管理 4. 協助門市營運與基本行政作業 5. 協助維持門市環境整潔與服務品質  【工作時間】 • 採早、晚班輪', 34000, 44000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_文浩實業有限公司', '文浩實業有限公司', '泰國WFH業務人員（電子零件）', '其他亞洲', '2026-09-07', 'https://www.104.com.tw/job/86b6i', '104', '1. 銷售電子零件，有經驗尤佳，無經驗亦可。  2. 開發潛在客戶，拓展市場，以達成業績目標。  3. 經常拜訪客戶，維繫客戶關係。  4. 基本底薪，高業績抽成制度。  5. WFH遠程工作，泰國上班，需每日工作日報。  6. 會遠端受訓1-3週（時間視情況而定）。  7. 語言能力需精通泰文。', 50000, 9999999, 'remote');
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_森品食品有限公司', '森品食品有限公司', '雲林食品業務（遠端工作/無底薪高獎金）(兼職)', '雲林縣斗南鎮', '2026-09-03', 'https://www.104.com.tw/job/8xk2t', '104', '【森品冷凍肉品】業務合作夥伴｜稀有部位 x 省工調理｜無底薪・高抽成・免囤貨  森品專注於提供具差異化的優質肉品與調理食品。從市面少見的稀有部位（如：雞牡蠣、雞松坂），到協助餐廳解決缺工痛點的省工調理包（舒肥雞胸、醃漬肉品、預炸類肉品），我們的產品線具備極強的市場競爭力。  隨著業務擴張，我們正在尋找熟悉餐飲生態、或擁有團購人脈的你，一起將這些「能幫老闆賺錢、省人工」的好食材推廣出去！  歡迎加入', 1000, 5000, 'remote');
