INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_蜂窩行銷有限公司', '蜂窩行銷有限公司', '短影音演員、模特（兼職）', '台中市豐原區', '2026-09-06', 'https://www.104.com.tw/job/8lp73', '104', '崗位職責： 1.根據短影音腳本拍攝，不僅限於短影音口播、服裝街拍、劇情拍攝（微劇情、第一人稱拍攝）  2.思維敏捷，形象氣質佳或風趣幽默，或對某個領域有良好的知識儲備，時間自由，具有一定的語言能力，有拍攝經驗或顏值出眾有特長可降低要求。  3.喜歡玩Tiktok，喜歡鏡頭前表演，願意從事演員工作者優先。  4.性格開朗，熱愛表現自己表現力強，善於調動氣氛，喜歡表演，戲精本精。  5.素質良好，責任', 200, 500, NULL);
