INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('6486', '翔評互動股份有限公司', '[PRM 系統] 客戶經營專員 Account Specialist : 台中', '台中市南屯區', '2026-08-26', 'https://www.104.com.tw/job/8bl3j', '104', '1. 協助新客戶On-boarding以及上線教育訓練。 2. 維護並發展現有客戶關係，提供高品質的客戶服務。 3. 了解客戶需求，基於AlleyPin的診所解決方案協助客戶解決通點。 4. 掌握診所客戶使用產品的情況，視狀況給予資源及協助，確保客戶滿意度。 5. 與內部業務、CS、產品團隊合作，確保客戶需求得到全方位的服務。 6. 設定和達成AM部門目標，推動客戶訂閱升級和續約。   客戶經營經', NULL, NULL, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_慧穩科技股份有限公司', '慧穩科技股份有限公司', '商務開發總監 Business Development Director', '台中市西屯區', '2026-09-09', 'https://www.104.com.tw/job/80kk4', '104', '- 負責各通路及策略型專案合作洽談、關係維護、商戶經營、產品業務推廣。 - 現有產品營收管理、經銷商通路開發合作，市調和執行支付類產品的開發和改進，確保產品的創新和競爭力。 - 負責帶領團隊開拓新客戶、維護現有客戶、達成銷售目標等。能擁有市場洞察力、客戶開發經驗、商業談判技巧等能力。 - 其他主管交辦事項，多為需要創新及有成就的專案。  專案業務主管是公司業務部門中的核心人員，負責協助開發新產品、', 700000, 3000000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_艾肯國際開發股份有限公司', '艾肯國際開發股份有限公司', 'LH【東南亞財務主管】年薪保底100萬~200萬', '桃園市蘆竹區', '2026-09-10', 'https://www.104.com.tw/job/86kuj', '104', '【工作地點】泰國春武里府  【薪資說明】年薪保底100萬~200萬(依面談)  【工作內容】 1.全盤帳務審核與覆核 2.月結報表編製與差異分析 3.預算控管與流程改善 4.稅務申報與會計師對接 5.財務規劃與行政申報  【職務條件】 •語言能力：英文(精通)、中文、泰文(加分) •具5年以上經驗 •可配合常駐海外者佳', 1000000, 2000000, NULL);
