INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_力躍運動健康管理顧問有限公司', '力躍運動健康管理顧問有限公司', '(嘉義兼職)樂齡團體指導員/預防及延緩失能指導員/運動教練/體適能指導員', '嘉義縣太保市', '2026-09-08', 'https://www.104.com.tw/job/87y9t', '104', '#授課地點＃ 嘉義各區 運動中心/社區據點/里民活動中心/日照中心/教會/失智據點/安養護理之家  1. 帶領中高齡者進行團體課程運動 2. 對中高齡者有高度熱誠具耐心，具親和力，願意指導中高齡族群相處 3. 運動、高齡、社工、物理治療、職能治療、護理，相關科系尤佳 4. 需有團體運動帶領經驗 5. 加分項目（證照） ⋆教育部體育署初級/中級體適能指導員 ⋆衛生福利部國民健康署/運動保健師 ⋆衛生', 600, 1000, NULL);
