INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_恒森數位有限公司', '恒森數位有限公司', '無須綁約|聲音直播主|愛唱歌', '新北市中和區', '2026-08-29', 'https://www.104.com.tw/job/94f1h', '104', '• 聲音直播主｜唱歌 | 聊天 |互動 一份 不露臉・完全遠端・時間彈性 的新型態工作 只要用 聲音或文字陪伴互動，就能創造收入。  不用通勤、不用打扮、沒有社交壓力， 在家就能完成，找回屬於自己的生活節奏。  • 工作內容 聲音直播主（Voice Streamer） 	•	不需露臉，以聲音聊天、唱歌、分享日常 	•	陪伴粉絲互動，創造情緒價值 	•	透過禮物與平台機制獲得收益  •工作特色 ✔', NULL, NULL, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_欣臨企業股份有限公司', '欣臨企業股份有限公司', '【欣利】南區通路業務專員(即飲通路)', '高雄市前鎮區', '2026-09-10', 'https://www.104.com.tw/job/7v0lp', '104', '1.負責南區即飲通路客戶,產品銷售與行銷活動執行,達成公司設定業績目標				 2. 以客戶為中心,執行區域業務計畫				 3.有效執行公司通路行銷活動,消費者促銷計畫及店家促銷活動,提升品牌知名度				4.蒐集市場價格資訊及競品行銷活動訊息,以便採取相關行動計畫', 38000, 42000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_元初生醫有限公司', '元初生醫有限公司', '【業務部】特約編輯（台北市大安）', '台北市大安區', '2026-09-09', 'https://www.104.com.tw/job/8xgop', '104', '※須有兩年以上出版社工作經驗（應徵請附參與製作過的書籍作品）。  【工作內容說明】  1. 負責醫療保健類型的新書企劃、編輯、潤稿、校對、發印等工作。 2. 與醫師（作者）溝通，確保出版品的品質和進度。 3. 協助行銷及業務團隊新書上市計劃。 4. 與公司旗下診所與各部門協同合作。 5. 採案件計酬方式，工作自由彈性。', 29500, 35000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_益普索市場研究股份有限公司', '益普索市場研究股份有限公司', '10月份短期兼職-電話訪問員(居家工作)花蓮', '花蓮縣花蓮市', '2026-09-08', 'https://www.104.com.tw/job/7s0kw', '104', '一、工作內容 透過電腦系統進行電話訪問，蒐集品牌忠誠度、客戶滿意度、民生消費意見，根據問題詢問受訪者意見並記錄於電腦上。  二、工作時間 1.排班彈性，達到最低排班標準即可 2.排班時段：【午班】13:30~17:30、【晚班】18:00~22:00、【午晚班】13:30~22:00 3.排班標準：一周至少5個班，平日至少3天 4.此為短期兼職，時間為【9/29-10/31】，請確認可完整配合後再', 196, 196, 'remote');
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_D+AF_晨希時尚股份有限公司', 'D+AF_晨希時尚股份有限公司', '校園大使', '台北市大安區', '2026-09-10', 'https://www.104.com.tw/job/90ogb', '104', 'D+AF招募校園大使，邀請熱愛社群經營與內容創作的在學學生加入。透過實際參與品牌推廣與內容產出，累積社群操作與行銷經驗，為未來職涯加分。  工作內容： ・於個人社群平台（如 Instagram、Threads）分享品牌相關內容 ・拍攝 Reels 或短影音，進行商品開箱與穿搭分享 ・回饋校園觀察與年輕族群趨勢 ・配合品牌參與指定活動或簡易影音支援  條件要求： ・大專院校在學學生（不限科系） ・熟', 196, 196, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_森品食品有限公司', '森品食品有限公司', '台北食品業務（遠端工作/無底薪高獎金）(兼職)', '台北市信義區', '2026-09-03', 'https://www.104.com.tw/job/8xieh', '104', '【森品冷凍肉品】業務合作夥伴｜稀有部位 x 省工調理｜無底薪・高抽成・免囤貨  森品專注於提供具差異化的優質肉品與調理食品。從市面少見的稀有部位（如：雞牡蠣、雞松坂），到協助餐廳解決缺工痛點的省工調理包（舒肥雞胸、醃漬肉品、預炸類肉品），我們的產品線具備極強的市場競爭力。  隨著業務擴張，我們正在尋找熟悉餐飲生態、或擁有團購人脈的你，一起將這些「能幫老闆賺錢、省人工」的好食材推廣出去！  歡迎加入', 1000, 5000, 'remote');
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_君苑家具CASA _鼎盛置業有限公司', '君苑家具CASA _鼎盛置業有限公司', '市場開發', '台中市西屯區', '2026-09-02', 'https://www.104.com.tw/job/8uzuf', '104', '1. 線上開發客戶，維繫穩定客戶關係。 2. 負責邀請客戶觀看課程直播 3. 開發潛在客戶，拓展市場，以達成業績目標。 4. 資料建檔、分析，市場規劃及執行。 5. 產品報價及產品展示，並處理帳款回收相關事宜。 6. 傳達及說明公司各項業務重大訊息、活動及產品。  本職位是公司業務拓展的重要角色，具有良好的發展前景。 歡迎符合條件的人才加入我們的團隊，一同拓展業務市場！', 30000, 42000, NULL);
