INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_佑煦旅宿管理顧問股份有限公司', '佑煦旅宿管理顧問股份有限公司', '新興區-飯店房務人員', '高雄市新興區', '2026-08-27', 'https://www.104.com.tw/job/933zb', '104', '1. 客房整理、公區整理。 2. 客房維護保養。 3. 協助主管完成盤點作業。 4. 完成主管交代之任務。 5. 願接受館別調動的挑戰。 6.可獨立完成整房作業。 7.介紹旅遊景點。 歡迎挑戰超房獎金', 31000, 32000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_台灣貝美企業有限公司', '台灣貝美企業有限公司', '業務專員(Food sales executive)-南部', '高雄市鳳山區', '2026-09-10', 'https://www.104.com.tw/job/7i7gv', '104', '1.開發潛在客戶，拓展市場，以達成業績目標。  2.定期拜訪經銷客戶，維繫穩定客戶關係。  3.負責國內業務接洽及訂單處理。  4.負責產品報價及產品展示，並處理帳款回收相關事宜。  5.負責業務推展，傳達及說明公司各項業務重大訊息、活動及產品。', NULL, NULL, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_康博集團_美加時尚美醫診所', '康博集團_美加時尚美醫診所', '【美加醫美 總部】醫美營運副總 (擴大營運展店、集團規模資源、美加醫美連鎖診所)', '台中市西區', '2026-09-02', 'https://www.104.com.tw/job/8e3fj', '104', '✪關於我們 | 康博集團．美加醫美診所 美加醫美診所，讓所有人由內而外擁有健康、美麗、自信的人生。 我們隸屬於康博集團， 集團深耕健康產業逾20年，總投入超過30億，致力打造台灣唯一的全方位大健康生活圈。 旗下事業橫跨： •康博診所（預防醫學與健康守護） •泰晶殿皇家SPA莊園（頂級紓壓與健康養身） •幸福村（幸福銀髮養生健康宅） 我們不只做醫美，我們打造的是「健康＋美麗」的永續照護系統。  ✪工', 1500000, 3000000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_康博集團_康博健康生活股份有限公司', '康博集團_康博健康生活股份有限公司', '健康代言人【中彰投區】獎金無上限、工作時間及地點彈性、無經驗者可', '台中市北屯區', '2026-09-09', 'https://www.104.com.tw/job/8abmg', '104', '「康博集團」已經營二十年，投入超過三十億，建構了台灣業界唯一大健康生活圈，康博診所為集團重要的服務之一。  我們為優良連鎖醫療體系，目前積極擴大服務據點，需要更多對守護健康有理想的人才一同加入我們，讓每個人「從健康、美麗，走向幸福之路」的健康生活願景  【我們的使命】 我們相信，幸福來自身心富足，讓我們用專業和熱情，陪伴所有人健康幸福呷百二  【我們的價值觀】 感恩善念、正向樂觀、互利共好、持續優', 1000, 999999, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_揚秝有限公司', '揚秝有限公司', '雲林縣麥寮鄉-羊乳配送員', '雲林縣麥寮鄉', '2026-09-01', 'https://www.104.com.tw/job/94rx9', '104', '1. 依據訂單詳情，仔細核對羊乳數量及品項； 2. 準確無誤地將訂單配送至顧客手中，準時送達且完好無損； 3. 提供優質顧客服務，並解答顧客疑問； 4. 協助客戶收款、帳單遞送及客戶異動資訊回報； 5. 維護客戶關係及保持車輛清潔、整潔； 6. 配合公司產品推廣及客戶需求服務 7. 公司上班時間：週一至週六(週日固定公休）  【合作條件】 * 具責任感、服務熱忱及良好溝通能力。 * 熟悉當地路況者', 196, 9999999, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_China labor watch', 'China labor watch', 'China Labor Watch 誠徵研究調查顧問', '台北市中正區', '2026-08-17', 'https://www.104.com.tw/job/94vu4', '104', 'China Labor Watch（中國勞工觀察，CLW）長期關注中國工人權益、全球供應鏈勞工問題及企業社會責任，透過工人訪談、實地調查、公開資料研究及政策倡議，研究全球供應鏈中的勞工權益與強迫勞動問題。  因應 CLW 在亞洲、歐洲及其他地區的研究與調查工作，我們現於台灣招募一名研究調查顧問（Research & Investigation Consultant），參與國際勞工權益、強迫勞動及全', 100000, 9999999, NULL);
