INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_映像網路多媒體企業社', '映像網路多媒體企業社', '正兼職線上互動人員『嘉義地區』', '嘉義市', '2026-09-06', 'https://www.104.com.tw/job/7azt4', '104', '我們是一間專注於直播內容與線上互動產業的團隊，提供完整培訓與專業輔導，協助新人快速進入直播領域。  工作內容主要透過平台進行直播互動，建立個人特色及粉絲社群，並依照個人風格規劃適合的內容方向。  【工作項目】  • 與觀眾進行即時互動與交流  • 經營個人直播內容及風格  • 維護粉絲關係與互動品質  • 學習直播相關技巧與內容規劃   【我們提供】  ✓ 完整新人培訓  ✓ 專人協助與營運支援', 30000, 60000, NULL);
