INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_台灣牙易通股份有限公司', '台灣牙易通股份有限公司', '(南區)牙材業務', '高雄市三民區', '2026-09-10', 'https://www.104.com.tw/job/82yzw', '104', '【牙材業務專員｜歡迎挑戰高成長市場！】 台灣牙e通是全台領先的牙科採購平台，目前已有超過 2,500 家牙醫診所開通註冊，整合超過百家牙材供應商，提供牙科耗材與器械的一站式採購服務，滿足診所超過 80% 的採購需求。 隨著平台快速成長，我們正在尋找一位充滿熱情、樂於與人互動、勇於挑戰業績目標的夥伴加入團隊，一同開拓牙科市場，創造更大的價值！  工作內容 ●定期拜訪牙醫診所，建立並維繫良好客戶關係', 35000, 80000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_台灣寶路多股份有限公司', '台灣寶路多股份有限公司', '汽車鑑定師 ( 新竹、桃園、苗栗 )', '新竹市', '2026-09-03', 'https://www.104.com.tw/job/7jbbo', '104', '汽車鑑定師的主要工作是針對中古車進行第三方的專業鑑定 並將鑑定結果提供給消費者作為購車參考 目的是提高中古車交易的透明度與信賴感，幫助消費者做出安心的購車選擇  上班地點：新竹，桃園，苗栗  具體內容如下：  • 檢查車輛外觀（鈑金、烤漆是否有修補或損傷） • 評估車輛結構（是否有事故痕跡、引擎室狀況等） • 填寫鑑定報告書，標示車況級別與備註 • 拍攝鑑定用照片，供網站刊登使用 • 與中古車商聯', 45000, 70000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_藝珂人事顧問股份有限公司', '藝珂人事顧問股份有限公司', '(韓國人歡迎! 企業提供工作許可證申請協助)【(全遠端) 外商 | Google 專案】Korean Content Analyst (具完整教育訓練，需具韓英文雙語能力) AMR_220', '台北市信義區', '2026-09-08', 'https://www.104.com.tw/job/8w6fp', '104', '【職務簡介】 作為 Korean Content Analyst，您將代表世界科技巨頭Google，負責審查韓國市場相關內容，依據政策、法規與平台標準進行判定，並在必要時進行海外跨團隊溝通與上報。此角色適合對 政策解讀、內容安全、語言分析、平台規範 有興趣的候選人。公司提供完整訓練，讓您快速掌握政策審核邏輯、案例分類與合規流程  【工作內容】 _審閱韓國市場的使用者內容，判斷是否符合平台與法規要求', 40000, 9999999, NULL);
