INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_騰龘室內裝修設計有限公司', '騰龘室內裝修設計有限公司', '室內設計師(桃園)', '桃園市中壢區', '2026-08-18', 'https://www.104.com.tw/job/6ir2u', '104', '1.藉由室內設計專業規劃，協助業主落實未來空間設計的想像與感覺，並  評估其可行性。  2.配合業主需求或提出更完善建議，檢討及規劃室內空間機能，使其發揮最高坪效或滿足業主個性化需求。   3.協助業主選擇裝修材料、窗簾、家具及飾品佈置，以統合室內整體風格設計，營造更舒適的理想環境。   4.繪製裝修施工圖，作為施工人員之施工準則及驗收標準。  5.配合業主需要進行現場監工', 40000, 55000, NULL);
