INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_火星生技股份有限公司', '火星生技股份有限公司', '社群團購主 / 團爸團媽 / 網紅KOL 商品銷售合作 (免囤貨高分潤)', '高雄市左營區', '2026-09-11', 'https://www.104.com.tw/job/93l69', '104', '團購主／直播主／KOL／斜槓合作夥伴 招募中！  想增加第二份收入，卻不知道從哪開始？ 我們提供完整的商品與銷售資源，讓您不用囤貨、不用自行開發產品，在家或遠距也能輕鬆展開團購與直播事業。 品牌:藥師健生活/Taizaku/Dr.Hold/Inyouso營養所/信賴生醫/樹飛雪/Bffect/韓系各大保養美妝等  我們提供 ✔ 保健食品、保養品、生活用品等多元國內外知名品牌商品 ✔ OEM／ODM', NULL, NULL, NULL);
