INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_沛宸健康管理顧問有限公司', '沛宸健康管理顧問有限公司', '雙北區-勞工健康服務護理人員（兼職）/限廠護經歷3年以上', '桃園市平鎮區', '2026-09-07', 'https://www.104.com.tw/job/92ooj', '104', '1. 推動職場健康計畫，如母性健康保護、異常工作負荷預防、人因性危害預防、執行職務遭受不法侵害預防計畫。 2. 職安法規之勞工健康服務事項及廠護應辦理事項。 3. 協助醫師執行勞工體檢相關作業。 4. 健康促進、健康管理及員工健康諮詢衛教推廣。  勞工健康服務護理人員在公司內擔任重要角色，負責推動健康管理、職業傷害預防、提供衛生指導及緊急處置等相關業務，未來仍有很大的發展空間。 歡迎符合條件的求職', 700, 1000, NULL);
