INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_岳凌科技有限公司', '岳凌科技有限公司', '純語音聊天主播｜無需露臉｜自由排班', '新竹市', '2026-09-09', 'https://www.104.com.tw/job/945ee', '104', '「在家兼職｜純語音聊天主播｜免露臉・無經驗可」  ▼ 職務說明 喜歡聊天，就有機會把你的聲音變成一份收入！  不用露臉、不用準備專業直播設備，也不要求唱歌或特殊才藝。 工作主要透過語音直播平台與用戶聊天互動、分享生活，建立自己的聲音特色與固定聽眾。  完全沒有直播經驗也可以！ 我們提供完整新人培訓，從平台操作、聊天技巧、直播互動到用戶經營，都有專人一步步帶領，讓新手也能安心開始。  ▼ 工作內容', 500, 9999999, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_新陳投資股份有限公司', '新陳投資股份有限公司', '影音剪輯製作', '台北市信義區', '2026-07-29', 'https://www.104.com.tw/job/8kusp', '104', '我們正在尋找對短影音有熱情的影音剪輯製作夥伴。  主要工作包含：  剪輯 製作YouTube，TikTok ，小紅書等影音，加入字幕、動畫特效及配置背景音樂、音效及配音，AI 配音或真人配音。', NULL, NULL, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_顏值女友文創有限公司', '顏值女友文創有限公司', '聲音直播｜不露臉直播｜語音廳直播主｜語音聊天｜聲音直播歌手', '新北市板橋區', '2026-09-08', 'https://www.104.com.tw/job/939xr', '104', '你喜歡聊天、唱歌、分享生活，或是用聲音陪伴別人嗎？加入我們，一支手機，就能開啟你的直播空間！  1.工作內容  * 與聽眾即時互動聊天，營造輕鬆歡樂的直播氛圍。 * 分享生活趣事、心情故事、時事話題，讓每場直播都有新鮮感。 * 唱歌、遊戲互動、情感陪伴、塔羅／星座等多元主題自由發揮。 * 參與語音廳活動、PK、派對及官方企劃，提升直播趣味性。 * 經營自己的粉絲群，累積忠實聽眾，打造個人直播特色。', 1, 500000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_全智新系統科技股份有限公司', '全智新系統科技股份有限公司', '半導體設備客服/裝機工程師(南科)', '台南市新市區', '2026-09-10', 'https://www.104.com.tw/job/8vtq7', '104', '1. 自動化設備於客戶端執行T0&T1裝機工程。 2. 自動化設備於廠內執行測試調整工程。 3. 自動化設備Move In與Docking。 4. 主管交付之任務。 5. 具有半導體或無塵室相關經驗尤佳。 6. 工作地點：半導體廠無塵室。 7. 配合外地出差者尤佳。 8. 南科Office備有宿舍。 **工作地點：南科為主,嘉義(AP7)、高雄ASE)視情況支援**', NULL, NULL, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_歐洲家顧問社', '歐洲家顧問社', '駐校代表/校園大使 （在校生)(全台)', '台中市西屯區', '2026-09-07', 'https://www.104.com.tw/job/7a7ny', '104', 'Work Content(可選其一):   ▲ 為學生做課程與方案的說明   ▲ 協助籌備校園宣傳活動：說明會校內宣傳、當天場地整理、現場資料收集   ▲ 校園內發放簡章＆貼海報：校內各公佈欄、系辦、教室、自習教室、宿舍、圖書館、餐廳、Ｋ書中心、社團活動   ▲ 運用自己的社群宣傳PO文：IG、Facebook、Blog、BBS、論壇、Dcard.....等      工作時間/上班地點彈性', 100, 30000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_美商昇迪凡科技術有限公司台灣分公司', '美商昇迪凡科技術有限公司台灣分公司', 'Search Engine Evaluator', '台北市中正區', '2026-09-10', 'https://www.104.com.tw/job/8mro4', '104', 'This is a long-term freelance project.  Requirement:  You are Native or Fluent Speaker of Chinese Traditional (Taiwan). You are fluent in English, as all Guidelines and certifications will be in Engli', 220, 240, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_艾福特股份有限公司', '艾福特股份有限公司', '產品經理 (新產品)', '高雄市仁武區', '2026-09-07', 'https://www.104.com.tw/job/94jpr', '104', '職務名稱：產品經理 (拓展產品線)  職務目的： 1. 觀察市場動態與競品狀況，規劃有機會脫穎而出的新產品方向 2. 開發並洽談潛力代理品牌與供應商，建立穩定又有競爭力的合作關係 3. 規劃與執行產品教育訓練，讓內外部同仁都能清楚理解產品亮點與優勢  你的日常工作將包括：   1. 與公司業務單位合作，鞏固並維護銷售產品線   2. 與供應商討論開發合作，建立及維持良好關係   3. 協調內外部資', NULL, NULL, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_艾美斯科技有限公司', '艾美斯科技有限公司', '測試工程師（遠端）', '台北市松山區', '2026-08-15', 'https://www.104.com.tw/job/93ecc', '104', '工作內容  1. 規劃與制定測試計畫（Test Plan），依據產品需求、系統規格及專案時程，規劃完整測試策略、測試範圍、測試時程及資源配置。 2. 撰寫與維護測試案例（Test Case），依功能需求與使用情境建立清楚且可重複執行之測試案例，並持續維護相關測試文件。 3. 執行系統功能測試（Functional Testing），驗證系統功能、流程及商業邏輯，確保產品符合需求規格與使用者期待。', NULL, NULL, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_台灣寶路多股份有限公司', '台灣寶路多股份有限公司', '汽車鑑定師（台南）', '台南市六甲區', '2026-09-03', 'https://www.104.com.tw/job/951cp', '104', '汽車鑑定師的主要工作是針對中古車進行第三方的專業鑑定 並將鑑定結果提供給消費者作為購車參考 目的是提高中古車交易的透明度與信賴感，幫助消費者做出安心的購車選擇  上班地點：台南  具體內容如下：  • 檢查車輛外觀（鈑金、烤漆是否有修補或損傷） • 評估車輛結構（是否有事故痕跡、引擎室狀況等） • 填寫鑑定報告書，標示車況級別與備註 • 拍攝鑑定用照片，供網站刊登使用 • 與中古車商聯繫、安排現場', 45000, 60000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_有家品牌整合股份有限公司', '有家品牌整合股份有限公司', '影像後期人員', '台北市內湖區', '2026-09-06', 'https://www.104.com.tw/job/8w7x6', '104', '｜工作內容｜ 商業修圖（產品、人物、情境圖） 影片剪輯（短影音、活動花絮、品牌形象影片） 素材管理、基本影片調色與修音 協助攝影師完成後期流程與交件 與設計、行銷部門協作完成專案製作 依專案需求調整剪輯節奏、畫面與風格  ｜必備條件｜ 熟悉 Photoshop / Premiere 為基本配備 有商業修圖或剪輯經驗 能獨立完成專案，願意接受修改與調整 具備時間管理能力，能應付多專案節奏 對影像細節', 10000, 9999999, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_森品食品有限公司', '森品食品有限公司', '桃園食品業務（遠端工作/無底薪高獎金）(兼職)', '桃園市中壢區', '2026-09-03', 'https://www.104.com.tw/job/8xiej', '104', '【森品冷凍肉品】業務合作夥伴｜稀有部位 x 省工調理｜無底薪・高抽成・免囤貨  森品專注於提供具差異化的優質肉品與調理食品。從市面少見的稀有部位（如：雞牡蠣、雞松坂），到協助餐廳解決缺工痛點的省工調理包（舒肥雞胸、醃漬肉品、預炸類肉品），我們的產品線具備極強的市場競爭力。  隨著業務擴張，我們正在尋找熟悉餐飲生態、或擁有團購人脈的你，一起將這些「能幫老闆賺錢、省人工」的好食材推廣出去！  歡迎加入', 1000, 5000, 'remote');
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_悟饕池上飯包_悟饕股份有限公司', '悟饕池上飯包_悟饕股份有限公司', '【南區】營運儲備督導-高雄、屏東地區', '高雄市左營區', '2026-09-07', 'https://www.104.com.tw/job/7zh3k', '104', '1.依據連鎖總部對於轄屬門市之既定政策，標準作業程序執行從事其營業工作 2.定期巡店，管理及督核門市品質、服務、清潔等執行狀況 3.執行追蹤門市經營績效輔導與管理。 4.顧客關係維護與門市客訴應對處理及門市緊急應變之處理與回報。 5.督導負責區域門市業績及各項指標，達成公司營運目標 6.負責門市教育訓練及開幕支援 7.協助門市與與總公司間的溝通與聯繫，傳達門市對各部門之意見及執行主管所交辦事項。', 40000, 45000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_米奧傳媒股份有限公司', '米奧傳媒股份有限公司', '主播經紀人', '台中市西屯區', '2026-09-01', 'https://www.104.com.tw/job/8re7m', '104', '你對娛樂產業充滿熱情嗎？喜愛與人交流、建立人際網絡嗎？你渴望在直播娛樂行業發揮你的專業，助力優秀的直播主和創作者實現他們的夢想嗎？如果你對這些問題的回答是肯定的，那麼我們正在尋找你！  【工作內容】 ＊透過各種平台、管道招募、拓展、挖掘有潛力的素人/網紅，成為直播主 ＊直播主培訓作業-包含直播技巧、app功能教導 ＊直播主日常關照-包含主播收益、活動資訊傳達，注意事項規定等等 ＊了解直播生態與自媒', 500000, 1000000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_藝珂人事顧問股份有限公司', '藝珂人事顧問股份有限公司', '桃園以北【全球前五百大外商企業】水處理技術服務工程師 #外勤彈性 #化工/環工 #年度調薪_ITS_842', '台北市士林區', '2026-09-07', 'https://www.104.com.tw/job/94wfn', '104', '✦職務亮點✦ 1. 以客戶端技術服務為主，非陌生開發型業務 2. 固定日班 09:00–17:30，週休二日、不輪班 3. 負責桃園以北客戶，外勤工作自主彈性高 4. 提供公務車或自備車津貼，油資及工作費用實報實銷   【工作內容】 • 至客戶廠區進行水質採樣、樣品測試及相關檢測作業 • 執行現場水處理儀器校正與系統例行養護 • 協助確認設備及水處理系統運作狀況，進行持續改善 • 負責現場化學藥劑', 40000, 50000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_元熙健康管理顧問有限公司', '元熙健康管理顧問有限公司', '【桃園市桃園區】勞工健康服務護理人員/顧問護理師', '桃園市桃園區', '2026-09-03', 'https://www.104.com.tw/job/92yqz', '104', '1.勞工之健康教育、健康促進與衛生指導之策劃及實施  2.依勞工健康保護規則辦理相關事項 3.職業病預防及管理  4. 公司配有管理系統執行臨場服務，免去人工繁雜報表，系統自動產生服務所需之報表 5.上班時間彈性', NULL, NULL, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('1313', '聯成電腦股份有限公司(聯成電腦/聯成外語)', 'AI應用規劃/AI辦公室技能應用講師 -台中站前認證中心', '台中市中區', '2026-08-28', 'https://www.104.com.tw/job/92dfz', '104', '【授課內容】 1. 生成式AI基礎知識、發展趨勢，強化Prompt能力。 2. 資料應用技能（如圖像、文字、簡報、聲音、影片、程式、數據分析、聊天機器人等）。 3. 相關之倫理與法律知識。 4. 熟悉 AI 工具（ChatGPT、Gemini、Midjourney 等）在文書與辦公室場景的應用。  【專業證照】 具「生成式AI能力認證」、「生成式AI辦公室應用認證」證照佳。', 400, 800, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_有家品牌整合股份有限公司', '有家品牌整合股份有限公司', '專案管理 Project Manager', '台北市內湖區', '2026-09-06', 'https://www.104.com.tw/job/8jqgb', '104', '●職務說明  如果你對品牌與設計產業充滿熱情，懂得如何協助創意團隊整合流程、保持節奏，讓好設計如期誕生。你擅長在變動中找到平衡，也樂於與人溝通協作，協助團隊一起完成專案任務。    1. 負責專案流程規劃、時程管理與資源分配。  2. 作為設計部與其他部門（行銷、影像、管理部）協作的主要窗口。  3. 協助整理專案 Brief、任務拆解與進度追蹤（使用 Asana 系統）。  4. 建立並優化設計', 10000, 10000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_順風生醫集團_順風美學診所', '順風生醫集團_順風美學診所', '醫美抗衰教育訓練專員', '台中市南屯區', '2026-09-09', 'https://www.104.com.tw/job/93y0s', '104', '1.規劃、組織和開展各種內部培訓活動； 2.編寫、維護和更新教材； 3.分析教育訓練成果，定期彙總報告； 4.通過各種培訓活動，促進企業文化的塑造； 5.參與和推動各項專案計劃； 6.完成主管交辦的其他相關工作。  我們正在招募集團內美容＆保健品, 醫學美容, 抗衰老預防醫學～等相教育訓練專員，這是一個非常重要的職位，有著廣闊的發展前景。您將協助負責培育和開發提升公司專業的能力和技能，幫助企業實現', 38000, 9999999, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_庠菻有限公司', '庠菻有限公司', '測試工程師', '台中市西屯區', '2026-06-25', 'https://www.104.com.tw/job/91f6z', '104', '我們是專注於技術服務的新創團隊，致力於為客戶提供網頁、App，以及前後台系統的設計與開發服務 隨著業務持續成長、案件需求快速增加，團隊正積極擴編，誠摯邀請優秀的您加入我們，一同打造更多精彩作品！ （提供全遠端工作環境，讓您能舒適自在的發揮專業與創意）  【工作內容】 1.根據功能需求，預估測試時程、量身打造測試計畫、撰寫測試案例 2.規劃、建立測試環境，開發、維護、改善測試程式 3.與開發團隊合作', 45000, 9999999, 'remote');
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_粲秝企業社', '粲秝企業社', '『正/兼職』 網路平台主持人｜《雲林可在家遠端》', '雲林縣虎尾鎮', '2026-09-04', 'https://www.104.com.tw/job/7jm7b', '104', '掌控直播新時代⚡ 直播成為時下年輕人的工作賺錢好機會  【工作內容】 使用智慧型手機或電腦設備開著視訊與線上會員回覆互動粉絲經營， 直播內容不拘：最熱話題、生活、流行、興趣、電影、動物、唱歌、跳舞... 面對鏡頭不排斥、基本能力表達、且願意學習應對及技巧即可。  【工作特點】 ☑免簽約  ☑免付費  ☑無經驗可   ☑時間彈性   ☑休假靈活 ☑公司皆提供完整教育訓練   ☑美顏軟體修飾增加您的信', 10000, 30000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_紅威媒體行銷股份有限公司', '紅威媒體行銷股份有限公司', '國內業務人員', '台北市大安區', '2026-09-07', 'https://www.104.com.tw/job/3s0m5', '104', '・遠端工作，不限所在區域 採 Work From Home，不需進公司，讓你更彈性地安排工作及客戶開發。  ・挑戰高獎金 歡迎具業務經驗、希望提升收入的夥伴加入。業績與獎金直接連動，能力越強，收入成長空間越大。  ・公司提供行銷資源 公司可提供品牌案例、提案素材及行銷資源，協助你更有效率地與客戶溝通及開發。  ・接觸不同產業，快速累積實戰經驗 在與品牌客戶洽談的過程中，你將深入了解各行各業的市場目', 29500, 100000, 'remote');
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_創星娛樂有限公司', '創星娛樂有限公司', '遊戲/實況直播主(TC)', '台中市西屯區', '2026-09-09', 'https://www.104.com.tw/job/8vcra', '104', '歡迎成為自媒體產業的一員，想瞭解現在最夯的直播平台及增加額外收入或者提高知名度、提升粉絲人數，創星娛樂給您最完整的資訊。   此為遠端工作，無地區限制，可在家工作、正職或者兼職皆可。  **遊戲/實況主播工作內容如下**   平台名稱 : 17Live  1.聚集網路人氣，吸引目標觀眾，與觀眾有良好的互動。  2.配合宣傳直播平台、公司經營之活動。  3.透過APP直播平台與觀眾互動，培養粉絲 。', 1750, 95250, 'remote');
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_崧達企業股份有限公司', '崧達企業股份有限公司', '(南區) 牙科通路 業務專員(無經驗可)', '高雄市鼓山區', '2026-09-10', 'https://www.104.com.tw/job/8lgrx', '104', '你可能沒聽過我們的公司，但只要你走進牙科診所，有機會看到我們代理的產品正在被使用。從3D列印機、牙科數位設計軟體，到放大鏡與CAD/CAM設備，我們的工作就是幫牙醫師跟牙技師把這些工具導入到他們的日常中。  我們與傳統醫材業務不同，我們在做的是「數位轉型的導入」。如果你對科技、醫療有興趣，或是就是想找一份能接觸新東西、工作有成就感的業務工作，這裡會是你很好的起點與發揮的地方。  ■ 主要工作內容：', 38000, 45000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('5381', '台灣光譜數據有限公司', '【外商】NetSuite ERP / Workday HCM 業務經理（Enterprise Sales Manager）', '高雄市三民區', '2026-08-15', 'https://www.104.com.tw/job/93kq2', '104', '我們正在尋找一位積極進取、目標導向且具備客戶服務思維的企業銷售經理。此職務將擔負拓展公司在台灣市場的重要任務，透過銷售雲端 ERP 與雲端 HCM 解決方案，與企業客戶建立穩固關係，並將商機轉化為長期合作夥伴關係。  職務說明 -	客戶關係管理：與潛在客戶、現有客戶及商業夥伴建立並維繫信任關係,挖掘並掌握新的商業機會。 -	雲端 ERP 與 HCM 銷售執行：管理完整銷售流程，包含名單開發與資格評', NULL, NULL, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_荳荳菊網路媒體行銷有限公司', '荳荳菊網路媒體行銷有限公司', '【好聲音招募｜無需露臉】語音直播／唱歌主播｜男女不限｜台港新馬皆可', '台北市大安區', '2026-09-03', 'https://www.104.com.tw/job/959am', '104', '喜歡唱歌、聲音有特色，但不想露臉直播嗎？  DoDoJu 現正招募各類型「好聲音」人才，不限直播平台、不限男女，也不要求直播經驗。  我們會依照您的聲線、唱歌風格、個人特色與可配合時段，協助評估並推薦較適合發展的平台與直播方向。  工作內容  * 語音直播／聲播互動 * 唱歌、點歌、音樂互動 * 與直播間聽眾聊天、互動 * 經營個人聲音特色與粉絲 * 依個人條件媒合適合的直播平台  招募條件  *', NULL, NULL, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_預約科技行銷股份有限公司', '預約科技行銷股份有限公司', '品牌公關(遠距)', '新北市新店區', '2026-09-11', 'https://www.104.com.tw/job/91bxx', '104', 'ezPretty致力於協助各產業實現雲端AI化，推動社會雲端科技之進步。  現於產品服務已進入高度複製的階段，並且需要加快市場複製的步伐。非常歡迎充滿企圖心和積極活力的夥伴加入我們，一同打造專業且創新的團隊氛圍。  2022 和 2024 -- 與Google合作 -- Google線上預訂團隊的認證和授權  2025 Gomaji, Line 和 Shopline 合作  2026 電子票券 聯', 50000, 70000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_Dr. MVP_汎卓科技股份有限公司', 'Dr. MVP_汎卓科技股份有限公司', '【無經驗也能輕鬆上手】數位翻轉教育語言課程顧問', '台北市中山區', '2026-09-10', 'https://www.104.com.tw/job/7dn05', '104', '1.提供客戶專業的英語課程規劃與諮詢，幫助客戶完成英文夢想 2.公司提供豐沛優質現有客戶名單，不須陌生開發 3.內勤業務，無須外出【免風吹日曬雨淋】 4.完整職前菁英培訓計劃，培育專業銷售管理人才 5.提供企業各部門職缺優先輪調機會，拓展國際視野 6.優於同業的高業績獎金，年輕就能實現百萬年薪  【薪資參考】 保障底薪『前二個月』＋業績獎金(無上限)，『平均月收80,000~200,000』  ★', 30000, 200000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_創星娛樂有限公司', '創星娛樂有限公司', '遊戲/實況直播主 (KH)', '高雄市新興區', '2026-09-09', 'https://www.104.com.tw/job/8vcrg', '104', '歡迎成為自媒體產業的一員，想瞭解現在最夯的直播平台及增加額外收入或者提高知名度、提升粉絲人數，創星娛樂給您最完整的資訊。   此為遠端工作，無地區限制，可在家工作、正職或者兼職皆可。  **遊戲/實況主播工作內容如下**   平台名稱 : 17Live  1.聚集網路人氣，吸引目標觀眾，與觀眾有良好的互動。  2.配合宣傳直播平台、公司經營之活動。  3.透過APP直播平台與觀眾互動，培養粉絲 。', 1750, 95250, 'remote');
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_澄築不動產顧問有限公司', '澄築不動產顧問有限公司', '(無經驗可)租賃代租代管人員', '台中市西屯區', '2026-09-01', 'https://www.104.com.tw/job/8wk4b', '104', '1.接收公司內部已開發的物件，轉PO上網.591等等---尋找等待有望租客來電 2.等待有需求房客來電，預約時間帶看 3.帶看房屋(主打高級新成屋社區帶看) 4.成交收斡旋轉訂金，和屋主確認租客品質及約簽約時間   歡迎有經驗之人員來電洽詢，業界福利最好 成交實拿最多!!! 公司時間最彈性!! 公司備有零食區 飲水區 座位區，多項資源陪您跑件，讓您月收5~40萬  人人時間有限，端看您時間放在哪!', 40000, 150000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_森先生清洗實業社', '森先生清洗實業社', '【苗栗遠端】專案助理-彈性排班', '苗栗縣苗栗市', '2026-09-10', 'https://www.104.com.tw/job/92omb', '104', '森清淨目標成為南部家電清洗第一品牌 主要清洗公司行號 / 公家機關 / 居家清洗 清洗品項包括冷氣 / 洗衣機 / 水管 / 水塔/床墊/沙發/除塵蟎 我們有別於一般市場上的個體戶 重視客戶服務、環境收善及14天服務保固 提供有保障的專業清洗服務 夥伴每年享有免費清洗福利  森清淨是一個有活力的團隊 我們每個月至育幼院行善洗樂 歡迎有工作熱忱也有善心的您 一起加入森清淨這個大家庭開心工作  森清淨', 196, 196, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_17LIVE_藝啟股份有限公司', '17LIVE_藝啟股份有限公司', '17官方主播 (無經驗可.有經驗佳)', '台北市中山區', '2026-09-10', 'https://www.104.com.tw/job/8ch47', '104', '17LIVE是個打破傳統、創造歷史，顛覆過往的直播社群娛樂平台！ 讓你用手機就能夠輕鬆分享生活點滴、展現你的才藝 讓你透過即時與人互動，豐富彼此生活 快加入17LIVE 大家庭，創造斜槓收入人生 成為17LIVER 展開你的直播旅程吧  只要你是： ▲對手機直播產業有高度熱忱者 ▲對新媒體有興趣者 ▲喜歡聊天與人互動 ▲想增加收入  即可享有加入福利： 1. 薪資豐富 2. 一對一專人教學 3.', 50000, 100000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_台福綜合工業有限公司', '台福綜合工業有限公司', '銷售專員【台中地區】', '台中市中區', '2026-09-08', 'https://www.104.com.tw/job/92vjf', '104', '【工作內容】   1. 開發潛在客戶，拓展市場，以達成業績目標。  2. 定期拜訪經銷客戶，維繫穩定客戶關係。  3. 負責業務接洽及訂單處理。  4. 負責產品報價及產品展示，並處理帳款回收相關事宜。  5. 負責業務推展，傳達及說明公司各項業務重大訊息、活動及產品。  6. 進行商品行銷，產品特色分析介紹，並提供客戶產品購買的建議。  7. 提供售後服務，處理客戶端之問題，給予完善的處理。', 40000, 150000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_欣佳合不動產有限公司', '欣佳合不動產有限公司', '助手學徒', '苗栗縣苗栗市', '2026-09-06', 'https://www.104.com.tw/job/8g18z', '104', '廣招新竹縣市、苗栗縣市，自由業夥伴 共同打拼 多份賺錢的自由工作 可以自己決定選擇 全職 或 兼職 ，可以選擇更高待遇福利 (依照個人能力決定)  工作時間自由彈性 工作地點自由彈性 可以不進公司 自由調控時間 完全人性化管理 工作內容  服務客戶買賣房屋土地   接洽客戶幫助處理相關問題 協助職場上工作夥伴共同服務客戶 團隊合作 互相扶持 互相照顧 工作區域 苗栗縣市全境  新竹縣市全境 誠摯歡', NULL, NULL, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_家樂生活嚴選團購_家樂學習窩教育科技有限', '家樂生活嚴選團購_家樂學習窩教育科技有限公司', '按業績計酬兼職銷售直播主團購主', '新北市新店區', '2026-09-08', 'https://www.104.com.tw/job/8cmtw', '104', '1.需現有經營社群經驗 2.社群粉絲或社群好友需要300名以上   目前只剩下分潤制的職缺 換算時薪一般直播主可達2000到3000 但保障時薪制直播主或團購主已額滿特此說明  因為商品內容有台灣的部分與海外業務 因此建議台灣與大陸雙邊銀行都有帳戶 方便我們雙邊會計出帳財務較為清楚   本公司介紹 我們是家樂學習窩教育科技有限公司關係企業有仲達一樂科技有限公司 與廈門家樂仲達生活科技有限公司 主要', 2000, 3000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_新加坡商約會吧股份有限公司台灣分公司', '新加坡商約會吧股份有限公司台灣分公司', '(兼職接案 / 遠端WFH) 兩性網紅 / KOL / 自媒體合作夥伴', '台北市大同區', '2026-09-07', 'https://www.104.com.tw/job/92r8t', '104', '你常常在 IG 或 Threads 上收到粉絲私訊問你「怎麼脫單」、「怎麼跟喜歡的人聊天」，或是看見留言區總是單身取暖取成一片嗎？  這些對情感、交友有強烈需求的單身粉絲，就是你影響力變現的藍海！  我們是【拍拖約會吧】，深耕兩性交友、實體聯誼與情感諮詢領域。我們發現許多兩性情感、穿搭改造、生活娛樂類的創作者，手上累積了大量渴望擴大社交圈、提升自信的「精準單身流量」，卻苦無優質且高回報的變現管道。', 50000, 9999999, 'remote');
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_秘密客股份有限公司', '秘密客股份有限公司', '(苗栗)汽車稽核神秘客(需有駕照)(限平日白天可執行)', '苗栗縣苗栗市', '2026-09-07', 'https://www.104.com.tw/job/95e2e', '104', '1.以匿名方式實際至指定稽核地點，針對服務品質和服務過程進行體驗和評價，並將此次體驗的稽核結果填寫至評核表   2.執行任務時段視案件規定時間，於規定日期前完成稽核任務即可   3.需配合事前訓練，協助錄音   4.需自備交通工具及電腦   5.薪資費用論件計酬，此為承攬職缺  6.需求地區：苗栗全區    【加入我們】 請至 MIMIC 官方網站 ➤ http://www.mimic.com.t', 450, 450, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_黃氏製藥股份有限公司', '黃氏製藥股份有限公司', '南區藥局業務（雲嘉南高屏）有經驗者', '雲林縣斗南鎮', '2026-09-06', 'https://www.104.com.tw/job/7vytk', '104', '此區域的藥局行銷業務', 45000, 80000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_金正禾數位有限公司', '金正禾數位有限公司', '產業分析顧問【兼職/斜槓/論件計酬】', '台北市大安區', '2026-09-10', 'https://www.104.com.tw/job/94w8n', '104', '在這裡，您將擁有揮灑專業的頂尖舞台，同步變現知識價值並拓展高階跨界人脈。  【關於我們】 我們成立於 2020 年，是一家專注於產業研究與專家諮詢服務的專業顧問團隊。 我們致力於連結全球頂尖產業權威與專業人士，為金融機構、投資法人及大型企業提供最關鍵的洞察與策略支援，我們尋找能精準剖析產業脈動的專家夥伴，共同打造高質量的產業諮詢與知識網絡。  【我們需要您的專業】 我們歡迎在以下任一領域具備 5', 13000, 30000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_良福保全股份有限公司', '良福保全股份有限公司', '清潔處-新北市大樓清潔員(板橋/中和/土城/新店)', '新北市新莊區', '2026-09-07', 'https://www.104.com.tw/job/92uun', '104', '案場各層樓垃圾處理 公共區域打掃 其他案場主管交辦事項', 30000, 9999999, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_晨昕科技股份有限公司', '晨昕科技股份有限公司', '長期派駐越南業務人才', '新北市中和區', '2026-09-08', 'https://www.104.com.tw/job/8w3wh', '104', '1. 新市場或新客戶業務開發及市場資訊收集。 2. 進出口貨物及交貨進度協調。 3. 現有客戶關係維護及服務。 4. 客戶反應事項彙整及客訴問題處理。 5. 與台北總部工作會報及溝通解決問題。 6. 主管交辦事項。', NULL, NULL, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_爍天股份有限公司', '爍天股份有限公司', '自媒體 剪輯手', '苗栗縣竹南鎮', '2026-02-24', 'https://www.104.com.tw/job/8sa4m', '104', '【喜歡剪片的你，來！我們缺你這一手】  你是不是…  每次看短影音都覺得：「這畫面我也會剪啊！」 就是沒人給你舞台？ 我們公司正在找「剪輯手」  無專業經驗可,由公司培訓 工作地點：苗栗／新竹（視情況調整） 月薪30,000元起，依能力調整 想拚更高薪？剪出來給我看！  工作內容：  剪輯 人物、商品、場景  畫面有感、有構圖  不怕累，敢挑戰，怕鏡頭晃請左轉  或私訊履歷＋作品集（手機拍也可以）', 30000, 45000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_永輝協同網路服務股份有限公司', '永輝協同網路服務股份有限公司', '在德國外資公司之財務會計薪資合規服務專員-雲端系統支援在家上班-需有德國永居證', '德國', '2026-09-01', 'https://www.104.com.tw/job/8k9nq', '104', '主要服務對象為在德國外資公司，依照合約，與團隊一同擔任客戶之跨國公司財務，會計，稅務等角色，主要任務在協助客戶編制每月管理報表，法規遵循並減少稅務風險。  最近接到德勒斯登的台積電下游廠商委託我們。 台積電下游廠商大部分是上市上櫃公司，都有自己的ERP系統。 上市上櫃公司是大公司 當然有自己的ERP, 為什麼還要我們的服務？ 由於德國税務局要求的財會系統是德文，且和一般ERP系統格式有些不同，德國', NULL, NULL, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_森先生清洗實業社', '森先生清洗實業社', '【台東遠端】專案助理-彈性排班', '台東縣台東市', '2026-09-10', 'https://www.104.com.tw/job/92omn', '104', '森清淨目標成為南部家電清洗第一品牌 主要清洗公司行號 / 公家機關 / 居家清洗 清洗品項包括冷氣 / 洗衣機 / 水管 / 水塔/床墊/沙發/除塵蟎 我們有別於一般市場上的個體戶 重視客戶服務、環境收善及14天服務保固 提供有保障的專業清洗服務 夥伴每年享有免費清洗福利  森清淨是一個有活力的團隊 我們每個月至育幼院行善洗樂 歡迎有工作熱忱也有善心的您 一起加入森清淨這個大家庭開心工作  森清淨', 196, 196, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_雅世數位有限公司', '雅世數位有限公司', '【全遠端/AI First】數位行銷專員｜Digital Marketing Specialist', '台東縣台東市', '2026-09-07', 'https://www.104.com.tw/job/9509v', '104', '★ 重要說明：這是 100% 全遠端職位，全台各縣市同步刊登 ★ 你可能會在好多縣市都看到這則職缺——不是詐騙，也不是重複張貼。 因為 104 的刊登制度目前不支援「全遠端／不限地區」的職缺，我們只能依縣市逐一刊登。 所以不管你住台北、宜蘭、台中、高雄、花蓮、台東，或澎湖金門馬祖，任選一則投遞即可，我們都會收到！  ────────── ■ AI First ■ ──────────  我們是一支', 45000, 55000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_森品食品有限公司', '森品食品有限公司', '花蓮食品業務（遠端工作/無底薪高獎金）(兼職)', '花蓮縣花蓮市', '2026-09-03', 'https://www.104.com.tw/job/8xk3d', '104', '【森品冷凍肉品】業務合作夥伴｜稀有部位 x 省工調理｜無底薪・高抽成・免囤貨  森品專注於提供具差異化的優質肉品與調理食品。從市面少見的稀有部位（如：雞牡蠣、雞松坂），到協助餐廳解決缺工痛點的省工調理包（舒肥雞胸、醃漬肉品、預炸類肉品），我們的產品線具備極強的市場競爭力。  隨著業務擴張，我們正在尋找熟悉餐飲生態、或擁有團購人脈的你，一起將這些「能幫老闆賺錢、省人工」的好食材推廣出去！  歡迎加入', 1000, 5000, 'remote');
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_泰瑞醫股份有限公司', '泰瑞醫股份有限公司', '客戶端技術支援工程師｜動物醫療系統｜Technical Support Engineer', '新北市中和區', '2026-09-09', 'https://www.104.com.tw/job/955mg', '104', '## 職務說明  我們提供動物醫院使用的雲端醫療資訊系統，並與多家醫療檢驗及設備品牌進行資料串接。此職位主要服務全台動物醫院，負責雲端病歷系統與醫療設備之串接支援、院內網路環境確認、異常排查及現場技術支援，並協助釐清設備端、網路端與系統端的問題來源，持續追蹤至案件完成。  當醫院現場發生「設備資料無法傳入病歷系統」、「原本可以使用，突然無法連線」、「偶發性資料傳輸異常」等問題時，問題可能來自院內網', 45000, 55000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_俊安投資股份有限公司', '俊安投資股份有限公司', '主播招募經紀人(高抽成)【遠端】', '台北市內湖區', '2026-09-08', 'https://www.104.com.tw/job/94wws', '104', '工作內容 主播招募經紀人｜高獎金｜無經驗可培訓  想挑戰高收入、不想領死薪水嗎？  我們正在招募【主播招募經紀人】，如果你對直播產業、網紅經濟有興趣，歡迎加入我們！  工作內容  • 開發與招募直播主播 • 協助主播簽約  我們提供  高抽成制度：按照主播的收入抽成，越多直播主，被動收入越高，收入沒有天花板 彈性工作模式，不需進辦公室  我們希望你具備  • 積極主動、具企圖心 • 良好的溝通協調', 40000, 80000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_新飛國際股份有限公司', '新飛國際股份有限公司', '[高分潤] 海外留遊學自由推廣業務代表 / 校園推廣大使 (免打卡)', '台北市松山區', '2026-09-04', 'https://www.104.com.tw/job/8zw1c', '104', '【這份職缺不是在找員工，而是找想把「人脈變現」的業務代表】  這不是一份傳統的打卡兼職，這是一場商業合作。 新飛留遊學擁有全台最頂尖的海外教育資源與後勤團隊。現在，我們要把前端的利潤讓出來，開放給擁有強大社交圈、懂自媒體、或是極度渴望增加收入的你。  遊戲規則極度簡單：你負責引流，我們負責收單。 你只需要發揮你的影響力，在你的校園、社群、親友圈中找出「想出國遊學/留學/參加夏令營」的人。 只要客人', 4000, 9999999, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_湛衡有限公司', '湛衡有限公司', '業務經理/ Business Development Manager （遠端工作）', '台北市中正區', '2026-09-04', 'https://www.104.com.tw/job/8we07', '104', '1. 制定並執行業務發展策略，通過開發新客戶和拓展現有合作夥伴賬戶來實現收入增長，達成業務增長目標。 2. 維護所有客戶/代理長期良好的合作關係。 3. 積極尋找新客戶資源及開拓新代理人網絡。 4. 協助客戶和代理人處理賬戶管理問題。 5. 持續進行市場調研，分析行業趨勢，挖掘新的業務機會，並及時向公司匯報最新信息。 6. 與市場團隊合作，提升品牌知名度並推動市場活動，參加行業有關的線上及線下會議', NULL, NULL, 'remote');
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_心家娛樂有限公司', '心家娛樂有限公司', '17LIVE官方兼職直播主(無經驗可.在家上班.高獎金)', '台中市東區', '2026-09-09', 'https://www.104.com.tw/job/7adni', '104', '【心家娛樂 - 17LIVE 官方兼職直播主熱烈招募中！】  我們是心家娛樂有限公司，自2017年成立以來，作為17LIVE內部的專業經紀公司，致力於發掘和培養有潛力的直播人才。 如果你對直播充滿熱情，無論有無經驗，這裡將是你實現夢想的舞台！  不論你是： - 無經驗，但願意學習成長的新手。 - 有經驗，卻遇到瓶頸的資深主播。  只要你肯學，我們提供專業經紀人一對一輔導，幫助你突破自我，打造個人品', 200, 500, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_米德奈股份有限公司', '米德奈股份有限公司', '國內業務 (北部)', '台中市霧峰區', '2026-09-02', 'https://www.104.com.tw/job/918gy', '104', '1. 開發北部板金雷射潛在客戶，拓展市場，以達成業績目標。 2. 負責北部業務接洽及訂單處理。 3. 負責產品報價及產品展示，並處理帳款回收相關事宜。 4. 負責業務推展，傳達及說明公司各項業務重大訊息、活動及產品。 5. 進行商品行銷，產品特色分析介紹，並提供產品購買的建議。 6. 提供售後服務，處理客戶端之問題，給予完善的處理。 7. 察覺客戶交易之異常狀況，並負責客訴問題之處理。 8. 底薪', 45000, 55000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_東奕傳媒行銷有限公司', '東奕傳媒行銷有限公司', 'AIGC人員', '高雄市小港區', '2026-09-06', 'https://www.104.com.tw/job/93320', '104', 'AiGGC技術人員熟悉各種Ai整合在電商平台行銷，對於這方面有經驗的可以兼職或正職都可以加入我們的團隊，', 33000, 38000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_富力康股份有限公司', '富力康股份有限公司', '苗栗產業維修耗材業務主管【原廠密集培訓、無經驗可】', '苗栗縣苗栗市', '2026-09-07', 'https://www.104.com.tw/job/7j0ev', '104', '機械設備是產業的根基，而金屬則是機械設備的核心。您的工作環境中充斥著各式各樣的設備，這些設備當初投入大量資金添購，目的就是提升效率、創造利潤。然而，當設備故障時，除了昂貴的汰換，我們是否還有其他更具成本效益的選擇？  我們的公司，正是專注於這類設備維修與再生的Magna 工業維修焊條專業團隊。現在，只要您願意努力，就能開啟穩定又高回報的事業之路。  工作內容： 1.開發與服務客戶以爭取訂單 2.對', 29999, 200000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_泓廣保全股份有限公司', '泓廣保全股份有限公司', '【正班】彰化彰濱工業區夜班保全員', '彰化縣線西鄉', '2026-09-07', 'https://www.104.com.tw/job/9332n', '104', '1. 人員進出登記管制，收包裹登記，貨運到貨登記。 2. 回應警報器並且調查引起警鈴的原因。 3. 保護被保全之人或物的安全。 4. 工廠巡邏廠區。 5. 給予意圖不良人士或入侵者警告。 6.其他交辦事項。', 32000, 35000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_得維國際股份有限公司', '得維國際股份有限公司', '高雄行銷業務專員', '高雄市苓雅區', '2026-09-10', 'https://www.104.com.tw/job/903vf', '104', '1. 負責開發新客戶及維護既有客戶關係。 2. 獲取市場情報並分析客戶需求，提供合適解決方案。 3. 推廣公司產品、教育資訊傳達，維持熱絡且穩定的合作關係。 4. 定期回報業務進度，協調內部資源，確保客戶滿意度。 5. 需具備良好溝通能力、抗壓性與團隊合作精神，熟悉市場趨勢及競爭環境。 6.負責台中區域  ■你的工作內容： 1.負責品牌髮品（洗護、燙護、造型等）銷售推廣 2.業績目標達成，開發新客', 38000, 60000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_澔冰文創有限公司', '澔冰文創有限公司', '愛聊天也能發光！一天兩小時聲播開啟你的新聲活', '新北市板橋區', '2026-08-30', 'https://www.104.com.tw/job/93lxu', '104', '如果你本來就喜歡聊天、喜歡認識新朋友， 那你的聲音，真的不該只停在生活裡。  在澔冰文創的語音交友廳， 你可以用最自然的方式開口， 和不同的人互動、聊天、分享生活， 把平凡的每一天，變成更有能量的新開始。  這裡不用露臉， 不用簽約， 不用準備複雜設備。  只要你願意嘗試， 每天花 2 小時， 就有機會開啟屬於自己的新舞台。  不管你是外向活潑、超愛交朋友， 還是慢熱一點、但很願意與人互動， 都歡', 30000, 30000, NULL);
