INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_泫錡文創工作室', '泫錡文創工作室', '喜歡聊天就來！聲音直播主招募中｜不用露臉！靠聲音開啟你的直播副業', '彰化縣彰化市', '2026-09-06', 'https://www.104.com.tw/job/95lrx', '104', '★不露臉也能發光！聲音直播主招募中 你有溫暖、迷人、幽默、或療癒的聲音嗎？ 你喜歡說故事、聊天、唱歌，或陪伴他人度過夜晚？ 我們正在尋找願意用聲音創造連結的你！  加入我們，你將擁有： ● 專屬聲音直播平台開通 ● 打賞分潤制度＋直播獎金獎勵 ● 彈性排班、零門檻入門、免費培訓支援  工作內容包含： ●進行聲音直播節目（陪聊、唱歌、說故事、主題互動等） ●經營與粉絲互動（聊天室、社群、聽眾任務）', 8000, 30000, NULL);
