INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_德昂資訊股份有限公司', '德昂資訊股份有限公司', 'BI 大數據軟體 銷售顧問 / 業務合作夥伴（兼職）', '台北市松山區', '2026-09-10', 'https://www.104.com.tw/job/8xiya', '104', '【職務說明】 想挑戰百萬年薪之外的第二曲線收入嗎？德昂誠邀具備產業人脈的銷售精英加入！ 德昂在 BI（商業智慧）領域深耕超過 17 年，擁有海峽兩岸 500 家以上知名企業客戶，是 Strategy 大中華區核心夥伴。我們擁有自主研發的 BI 系列產品 Imobilebi, DemandETL，以及獨創的MVDA實施方法論，和針對不同產業的六大分析應用主題，並致力於 ABC 生態策略（AI、Big', NULL, NULL, NULL);
