INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_煦願活動整合有限公司', '煦願活動整合有限公司', '兼職婚禮顧問', '台北市信義區', '2026-09-06', 'https://www.104.com.tw/job/8xm9p', '104', '【煦願婚禮顧問｜婚禮顧問夥伴招募】  有些人喜歡婚禮，是因為熱鬧與漂亮。 而我們更在意的是—— 那一天，誰被好好放在心裡。  在煦願，我們陪伴新人，把一場婚禮變成「人生中一段被理解的時刻」。 不追求制式流程、不複製模板， 而是協助新人找到屬於他們的節奏、關係與情感位置。  如果你相信 婚顧不只是執行者，而是「站在新人身邊的人」， 那麼，這份工作很可能就是為你準備的。  【在煦願，你會成為什麼樣的角', 20000, 9999999, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_跨傳媒體有限公司', '跨傳媒體有限公司', '影片剪輯(兼職/遠端工作)', '台北市松山區', '2026-09-10', 'https://www.104.com.tw/job/7t3vo', '104', '【工作內容】 -這是一份兼職工作（全台北地區皆適任） -工作內容主要是協助公司品牌客戶（YT頻道名稱：VISION THAI 看見泰國）影片剪輯與縮略圖製作  【工作技能與條件】（有*號為必要） *1. 熟悉剪輯軟體 Premiere *2. 熟悉影片剪輯流程，可獨立完成後製剪輯（剪輯、特效、字幕、音效、音樂等） *3. 擅長剪輯Vlog影片 *4. 擅長製作影片縮略圖 *5. 至少3年(含)以上', 1, 10000, 'remote');
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('8046', '鑫長鴻竹南電子股份有限公司', '★急徵★【新竹】外派品檢員/目檢員◆正職非派遣◆外派津貼◆加班費另計◆每月績效獎金', '苗栗縣竹南鎮', '2026-09-07', 'https://www.104.com.tw/job/935bs', '104', '日班外派目檢 ▪️錄取即正職員工，長期派遣客戶端，固定班別 **工作地點需長期派駐封裝廠，著全套無塵服，無法接受者請勿投履歷**  1. 在客戶端維繫客戶關係。 2. 具基礎PCB相關檢驗能力、有檢驗經歷尤佳 3. 負責客戶端物料品質，確認客戶端來料情況。 4. 需能臨場反應靈活應對。 5. 穿全套無塵服作業 6. 底薪將依工作年資與經歷調整 7. 可配合加班者,優先錄取 8.每月配合獎金3000', 30200, 60000, NULL);
