INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_芒檸檬事業社', '芒檸檬事業社', '全職｜LIVE 網路直播主 免簽約', '新北市中和區', '2026-08-17', 'https://www.104.com.tw/job/87710', '104', '【正職直播夥伴｜自媒體發展／遠端彈性】 我們正在招募長期配合的直播夥伴，透過公司配合的平台、培訓與流量支援，穩定經營屬於自己的直播事業。適合有企圖心、想掌握收入彈性、追求長期發展的你  ✦ 優越的獎金制度 ✦  ◉ 工作內容 ▪ 透過直播平台與觀眾互動、聊天、分享日常 ▪ 自由排班（每月穩定開播 60 小時以上佳） ▪ 不需銷售、不用囤貨，公司協助定位直播風格 ▪ 可遠端執行，免通勤、不打卡 ▪', 360000, 700000, NULL);
