INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_台灣尼爾森愛科股份有限公司', '台灣尼爾森愛科股份有限公司', '苗栗全區-神秘訪客', '苗栗縣銅鑼鄉', '2026-09-07', 'https://www.104.com.tw/job/9195p', '104', '這是一個長期的兼職工作，利用工作之餘，幫自己額外增加收入，如您對於這個工作有興趣，歡迎投遞履歷~  工作內容說明 :  1. 專案開始前參加教育訓練 2. 於專案執行期間內完成測試任務 3. 以一般消費者模式至指定門市進行測試 4. 執行測試過程不可暴露神秘客身份 5. 如果有需要，測試過程可能需拍照、錄音(需自備手機、或其他拍照/錄音工具)，或錄影(公司提供) 6. 測試完成後填寫測試心得回饋、', 100, 600, NULL);
