INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_森品食品有限公司', '森品食品有限公司', '台東食品業務（遠端工作/無底薪高獎金）(兼職)', '台東縣台東市', '2026-09-03', 'https://www.104.com.tw/job/8xk3h', '104', '【森品冷凍肉品】業務合作夥伴｜稀有部位 x 省工調理｜無底薪・高抽成・免囤貨  森品專注於提供具差異化的優質肉品與調理食品。從市面少見的稀有部位（如：雞牡蠣、雞松坂），到協助餐廳解決缺工痛點的省工調理包（舒肥雞胸、醃漬肉品、預炸類肉品），我們的產品線具備極強的市場競爭力。  隨著業務擴張，我們正在尋找熟悉餐飲生態、或擁有團購人脈的你，一起將這些「能幫老闆賺錢、省人工」的好食材推廣出去！  歡迎加入', 1000, 5000, 'remote');
