INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_洛華納醫學科技股份有限公司', '洛華納醫學科技股份有限公司', '牙科業務人員_桃竹區（遠端）', '新北市中和區', '2026-09-08', 'https://www.104.com.tw/job/92cmb', '104', '1. 區域桃園、新竹，醫院使用15年專利產品，推展牙醫診所藍海市場。 2. 定期拜訪經銷客戶，維繫穩定客戶關係。 3. 負責國內業務，接洽及訂單處理。 4. 負責產品報價及產品展示，舉辦產品說明會。 5. 負責業務推展，傳達及說明公司各項業務重大訊息、活動及產品。 6. 進行商品行銷，產品特色分析介紹，並提供產品購買的建議。 7. 提供售後服務，處理客戶端之問題，給予完善的處理', 45000, 60000, NULL);
