INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_漾活企業有限公司', '漾活企業有限公司', 'IG Reel/TIKTOK/Youtube影音腳本企劃/攝影剪輯/IP頻道經營操盤', '台北市中山區', '2026-09-10', 'https://www.104.com.tw/job/8tezn', '104', '工作內容  1. 公司IP頻道或專案之腳本企劃及拍攝製作剪輯  2. 節目內容製作產出、頻道經營與曝光宣傳 3. 根據公司IP品牌與頻道定位企劃執行影音內容拍攝剪輯後製，     以多元內容和觀點，擴大受眾，深化品牌影響力。 4. 每周數據觀測與分析，優化節目及頻道收聽表現。', 1500, 9999999, NULL);
