INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_台灣希悅爾股份有限公司', '台灣希悅爾股份有限公司', 'Service Engineer服務工程師（南區）', '台南市東區', '2026-09-08', 'https://www.104.com.tw/job/8jx7h', '104', '1.	服務區域：雲林，嘉義，台南，高屏 2.	居家辦公模式：能自律&自我管理時間 3.	居住地:建議中部以南  工作內容： 1. 處理故障或機器問題並努力解決而讓客戶完全滿意。 2.. 根據客戶服務協議或銷售合同提供設備維修服務。 3. 與業務偕同並達成年度業績成長。 4. 積極推廣和“銷售”服務協議和備件。 5. 積極尋找現場服務機會，不僅促進服務銷售，而且增加時間利用率。 6. 建立良好的客戶', NULL, NULL, 'remote');
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_鈺暉食品有限公司', '鈺暉食品有限公司', '鈺暉食品北區駐區業務專員', '花蓮縣吉安鄉', '2026-08-07', 'https://www.104.com.tw/job/92fyj', '104', '【工作內容】 1.負責推廣本公司剝皮辣椒、辣椒醬相關商品 2.維繫現有客戶關係，拓展新客源 3.規劃並執行實體賣場及全台通路行銷策略 4.分析市場動向，回饋競爭資訊與銷售報告  【職務需求】 1.具備強烈責任心與自我管理能力 2.優秀溝通能力與談判技巧，具業務經驗者尤佳 3.熟悉台灣各大賣場通路（如全聯、家樂福、7-11等）實體行銷操作 4.對台灣各地名產、伴手禮市場有深入了解者佳 5.能適應外勤', 35000, 9999999, NULL);
