INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_株式会社山陽工房_SANYO KOUBO', '株式会社山陽工房_SANYO KOUBO Co., Ltd.', '建築設計(廣告看板)・遠端工作(僅限日本或台灣居民)', '日本', '2026-09-09', 'https://www.104.com.tw/job/8tkik', '104', '＜サインと建築的視点から顧客へのアドバイス＞  サインの設計をお願いします。 「クライアントより依頼 → 打合せ・現地調査 → 作図提案 → 製作管理 → 施工監理 → 引渡し」 また、電気やデザイン分野の知識習得に視野を広げて頂きたいと思っています。  ＊出社は不要でリモートワーク（在宅勤務）となります。', 50000, 105000, 'remote');
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('1313', '聯成電腦股份有限公司(聯成電腦/聯成外語)', '【菜鳥救星】英文影音課程講師', '台北市大安區', '2026-08-28', 'https://www.104.com.tw/job/82fc7', '104', '【工作內容】 我們正在積極招募英語課程 (節慶/旅遊/翻譯/文化…等) 線上直播講師，提供優於業界的薪資條件、開班穩定，歡迎對英語教學有熱忱的老師加入！  職務內容：英語線上直播課程授課，需有配合度高且可長期授課，具備專業英語能力的老師。   ※必備條件 1. 1年以上教學經驗 2. 獨立規劃課程能力（撰寫課程大綱、教材） 3. 教學生動、有熱忱、敬業樂於與學員互動 4. 可配合平日晚上及假日白天', 450, 550, NULL);
