INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_舶克國際有限公司', '舶克國際有限公司', '維修倉管', '新北市三重區', '2026-09-10', 'https://www.104.com.tw/job/8t22w', '104', '1.船務事務管理及船組員工作支援 2.遊艇保養維修及基本水電技能 3.協助總公司、碼頭及遊艇船務等事務 4.公司及主管交辦事務 5.配合船班的輪班時間', 35000, 9999999, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_泫錡文創工作室', '泫錡文創工作室', 'ಡ⁠ ͜⁠ ⁠ʖ⁠ ⁠ಡ颱風天不想出門/在家工作/聲播免簽約', '台北市信義區', '2026-09-06', 'https://www.104.com.tw/job/9326v', '104', '颱風天不想出門？ 下雨天不想通勤？ 只要在家，一支手機就能開始工作  只要你肯努力、肯認真， 公司福利多多！  每個月都有獎金，不定期聚餐、聚會。 新進主播平均收入約為2,000元至10,000元， 穩定開播並持續經營後， 兼職收入可達20,000元以上，  實際收入依個人表現及投入程度而定。  不用擔心颱風、下雨影響工作， 在家就能輕鬆開播，把空閒時間變成收入  只要你肯努力，六位數收入不是問題', 400, 9999999, 'remote');
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_中康生醫股份有限公司', '中康生醫股份有限公司', '業務代表｜業務主任 (新竹以北）', '台北市內湖區', '2026-09-02', 'https://www.104.com.tw/job/8xhjy', '104', '鄰近健康｜業務代表／業務主任 藥局通路｜健康服務推廣｜社區健康產業  【職務定位】  你不只是業務，而是推動社區藥局轉型的第一線夥伴。  鄰近健康正在打造「一站式社區健康中心」，協助社區藥局導入健康服務、保健商品、醫材輔具、長照資源與會員經營系統。我們正在尋找一位願意走進藥局、理解藥師需求，並能把服務真正推動落地的業務代表／業務主任。  這是一份適合有業務經驗、喜歡與人互動、願意進入醫療健康產業發', 50000, 9999999, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_康揚股份有限公司', '康揚股份有限公司', '【智能醫療】(北部) 外勤業務~歡迎轉職人才', '台北市中山區', '2026-09-07', 'https://www.104.com.tw/job/83ujg', '104', '你對台灣銀髮商機、醫療科技有興趣嗎? 你是熱血業務，想用一己之長改變台灣醫材現況嗎?  如果你具備了以下的能力，你就是我們在找的人  【關於你】 1.熱血醫療輔具業務代表，經營既有醫療器材門市通路 2. 定期拜訪北區客戶，維繫穩定客戶關係，執行銷售和營銷策略，例如商店陳列、教育訓練、促銷活動…等。 3. 開發區域內潛在醫材、藥局、機構客戶，以達成業績和產品組合目標 4. 定期報告銷售進度及市場佔有', 36000, 9999999, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_矽煬自動化系統有限公司', '矽煬自動化系統有限公司', '自動化系統業務(有底薪)', '南投縣草屯鎮', '2026-09-10', 'https://www.104.com.tw/job/8kmmr', '104', '1.開發潛在客戶，拓展市場，以達成業績目標。 2.定期拜訪經銷客戶，維繫穩定客戶關係。 3.負責國內業務接洽及訂單處理。 4.負責產品報價及產品展示，並處理帳款回收相關事宜。 5.負責業務推展，傳達及說明公司各項業務重大訊息、活動及產品。', 40000, 9999999, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_戰國策網路科技股份有限公司', '戰國策網路科技股份有限公司', 'AI軟體B2B開發業務(底薪六萬/周休三日 台中)', '台中市西屯區', '2026-09-01', 'https://www.104.com.tw/job/8tp72', '104', '工作內容 * 開發並拓展企業客戶，推廣本公司 AI客服系統 與 SEO服務 * 掌握B2B客戶需求，提供解決方案與顧問式銷售 * 負責業務開發流程：名單開發 → 洽談 → 提案 → 成交 → 客戶維護 * 協助客戶導入AI客服系統，並結合SEO服務提升品牌曝光與流量轉換 * 與技術團隊合作，回饋市場需求與產品優化建議 * 達成公司設定的銷售目標，並持續開拓新市場  職務需求 * 具備 **B2B業', 60000, 150000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_唯一實驗教育有限公司', '唯一實驗教育有限公司', '兼任老師', '高雄市前鎮區', '2026-09-09', 'https://www.104.com.tw/job/8lao0', '104', '<公司簡介 > Only實驗教育社會企業台灣首創：陪伴拒學生/休學生轉自學能高中畢業並到社會就業，避免學生成為繭居族。我們的課程設計理念並非現今的一綱多本，而是採無綱無本，以學生為中心，結合杜威教育理論、生涯規劃輔導和PBL教學法等，並運用地方創生資源探索生涯，打造平價奢華的學習歷程檔案也是就業的履歷表！   *此職缺會跟傳統教育非常不同，工作地點為你住的城市並結合線上       需參加教育訓練', 200, 500, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('1313', '聯成電腦股份有限公司(聯成電腦/聯成外語)', '【菜鳥救星】Vibe Coding AI程式線上直播課程講師', '台北市大安區', '2026-08-28', 'https://www.104.com.tw/job/8rp8h', '104', '工作內容 我們正在招募線上直播講師， 希望對程式設計教學有熱忱， 喜歡在直播教室線上和學員互動的講師加入。 開班穩定、不定期舉辦實體/線上交流會。 --------------------------------------------------------------------------------  ※必備條件 : 1. 具有程式相關工作經驗至少2年 2. 具有相關教學經驗1~2年 3.', 700, 900, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_保進文教事業股份有限公司', '保進文教事業股份有限公司', '小巨園補習班-國小課業指導老師', '新北市土城區', '2026-09-11', 'https://www.104.com.tw/job/93g7b', '104', '1.指導學童作業，協助輔導加強課業，做課業的複習 2.與家長溝通讓家長充分了解孩童學習狀況以及生活狀態 3.代替家長照顧學童，處理學童在班內一切生活事務 4.處理家長的投訴或者要求，與家長協調解決 5.(如親子活動...) 6.主題式課程教學、協助外師授課，並協助活動規劃與執行 7.櫃檯行政事務執行 時間: @寒暑假上班時間8:30到18:30 @其他時間11:00到19:30 @週二下午14:0', 32000, 35000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_富康活力連鎖藥局_富康活力醫藥股份有限公', '富康活力連鎖藥局_富康活力醫藥股份有限公司', '【高雄三民】藥局門市人員(大夜班)｜有藥局經驗薪資可談｜高薪、穩定', '高雄市三民區', '2026-09-08', 'https://www.104.com.tw/job/92n9j', '104', '如果你近期因藥局體系營運調整、門市停業或組織變動而正在尋找新的工作機會，我們誠摯邀請你加入富康活力連鎖藥局。  富康活力藥局為穩定發展中的連鎖藥局品牌，致力於提供專業、溫暖且值得信賴的健康服務。我們重視每一位同仁的專業發展與工作安心感，提供完整制度與培訓，讓夥伴能在穩定的環境中持續成長。  【工作內容】 1. 門市顧客服務與健康諮詢 2. 商品介紹與銷售（保健食品、醫療用品等） 3. 商品陳列與庫', 34000, 44000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_藝康企業股份有限公司', '藝康企業股份有限公司', '餐廳飯店客戶-台北區域業務代表(歡迎連鎖餐飲/飯店店長轉職)', '台北市士林區', '2026-09-10', 'https://www.104.com.tw/job/8bvy9', '104', '藝康(Ecolab)是眾多國際連鎖飯店、米其林餐廳幕後的「安全與清潔守護專家」。在藝康，我們不僅提供全面科學的解決方案，更致力於保護與生命息息相關的重要資源。加入我們，將您的餐飲門店管理經驗，轉化為影響全球食品安全與永續發展的專業力量！  您將透過區域經理(Territory Manager In Training)培訓計畫透過完整的教育訓練以及實地工作演練，成為獨當一面的區域業務經理。  -->', NULL, NULL, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_仲駿股份有限公司', '仲駿股份有限公司', '業務工程師_BU2', '台北市內湖區', '2026-09-10', 'https://www.104.com.tw/job/92nju', '104', '•	負責Socket & Connector產品業務推廣。 •	維持既有客戶、陌生開發客戶及拓展產品市場。 •	與原廠業務和技術人員定期拜訪客戶，維護客戶關係。 •	負責每年、每月業績預估及達成。 •	進行市場及相關廠商信息收集和分析，         提供公司和原廠做為未來產品策略及銷售策略參考。 •	不排斥業務性質，無相關經驗可！ •	電機電子、機械、工業工程相關科系為優先。 •	工作地點：內', 38000, 60000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_美商新勢力科技有限公司台灣分公司', '美商新勢力科技有限公司台灣分公司', '日本高級銷售客戶經理', '台北市中山區', '2026-09-07', 'https://www.104.com.tw/job/8tn51', '104', '關於這份工作 NewPower Worldwide 是全球成長最快的電子零組件獨立分銷商，致力於為全球客戶提供高品質解決方案。我們目前正在尋找一位 高級銷售客戶經理（Senior Sales Account Manager） 加入我們充滿活力的團隊，為公司在業界的持續成功做出貢獻。  工作概述 高級銷售客戶經理將專注於推動日本市場的業務增長，同時探索亞太地區的商機。此角色負責開發新客戶、維護及培養', 105000, 150000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_漾活企業有限公司', '漾活企業有限公司', '服裝服飾車縫師/裁縫師夥伴', '台北市中山區', '2026-09-10', 'https://www.104.com.tw/job/8mhke', '104', '服裝服飾 車縫師/裁縫師夥伴  1.協助公司從事長照服裝等紡織服飾的製作剪裁縫製 2.工作時間彈性可討論 4.可遠距居家上班|家庭代工 5.需自備縫紉機 6,雙北林口桃園地區皆可', 200, 9999999, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_綠楓顧問有限公司', '綠楓顧問有限公司', '美國簽證與移民法助理', '台北市大安區', '2026-09-05', 'https://www.104.com.tw/job/93n2e', '104', 'Hey there!  We are a U.S. based visa & immigration law firm.  Most of our team members are originally from Taiwan, and many of our clients are Taiwanese.  We are looking to hire in Taiwan several supp', 60000, 9999999, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_漢補世家中醫診所', '漢補世家中醫診所', '診所櫃台人員', '台北市中山區', '2026-09-08', 'https://www.104.com.tw/job/8yhkf', '104', '【主要工作內容】 1.櫃枱患者服務 2.行政作業 3.環境清潔維護 4.配合公司職務安排  *須具備1年以上櫃台或客服工作經驗 *需有穩定的情緒  月休8~9天(周日全天休假)  工作地點： 台北市大安區、中山區 (近捷運站)', 34000, 38000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_岳凌科技有限公司', '岳凌科技有限公司', '線上語音互動主播｜居家兼職｜免露臉｜彈性排班', '台中市北屯區', '2026-09-10', 'https://www.104.com.tw/job/94b9f', '104', '加入我們，讓聲音成為你的優勢！  想找一份能自由安排時間、不受地點限制的工作嗎？  如果你喜歡聊天、分享生活、陪伴他人，卻不喜歡露臉直播，我們提供一個更自在的選擇。  全程透過語音互動即可開始，在家、一支手機與耳機就能工作。  我們重視每一位夥伴的成長，無經驗也不用擔心，從零開始都會有專人協助。  ⸻  【工作內容】  使用平台進行語音直播  與玩家聊天互動、陪伴交流  維持直播間氣氛與互動品質', NULL, NULL, NULL);
