INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_永琁地政士事務所', '永琁地政士事務所', '代書地政士(須具備證照)/地政士助理', '桃園市桃園區', '2026-08-15', 'https://www.104.com.tw/job/94vdv', '104', '【工作職責】  不動產過戶登記（買賣、贈與、繼承、信託等）及抵押權設定塗銷。  地政、國稅局、稅捐處等機關外勤送件與案件跟進。  遺產稅、贈與稅及房地合一稅試算與申報協助。  不動產契約撰寫、客戶地政稅務諮詢與案件聯絡窗口。  【職務要求與待遇】  地政士需具備普考地政士證照；助理無經驗可，事務所提供完善培訓。  具良好溝通協調能力、細心耐用、有汽機車駕照佳。', 33000, 500000, NULL);
