INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_龍平安租車有限公司', '龍平安租車有限公司', '機場接送職業駕駛(居住於台南各行政區）', '台南市中西區', '2026-09-07', 'https://www.104.com.tw/job/8x1nc', '104', '【誠徵機場南部專案駕駛  】 開公司車跑接送工作    薪資及休假說明：  1.自行排休 2.勞健保(保在公司底下) 3.達標責任營業額後車資50％抽成歸駕駛 ※另外有與政府單位合作，如符合國軍退除役官兵穩定就業津貼發給辦法資格者（第一類及第二類）   可協助申請額外補助津貼，每月額外補助金額$4,000~$8,000     1. 負責機場與周邊地區的乘客接送服務，確保旅客安全與準時抵達目的地。', 40000, 65000, NULL);
