INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_森先生清洗實業社', '森先生清洗實業社', '【彰化遠端】行銷設計-彈性排班', '彰化縣彰化市', '2026-09-09', 'https://www.104.com.tw/job/92omw', '104', '森清淨目標成為南部家電清洗第一品牌 主要清洗公司行號 / 公家機關 / 居家清洗 清洗品項包括冷氣 / 洗衣機 / 水管 / 水塔/床墊/沙發/除塵蟎 我們有別於一般市場上的個體戶 重視客戶服務、環境收善及14天服務保固 提供有保障的專業清洗服務 夥伴每年享有免費清洗福利  森清淨是一個有活力的團隊 我們每個月至育幼院行善洗樂 歡迎有工作熱忱也有善心的您 一起加入森清淨這個大家庭開心工作  森清淨', 196, 196, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_台灣尼爾森愛科股份有限公司', '台灣尼爾森愛科股份有限公司', '南投全區-神秘訪客', '南投縣埔里鎮', '2026-09-07', 'https://www.104.com.tw/job/8sege', '104', '這是一個長期的兼職工作，利用工作之餘，幫自己額外增加收入，如您對於這個工作有興趣，歡迎投遞履歷~  工作內容說明 :  1. 專案開始前參加教育訓練 2. 於專案執行期間內完成測試任務 3. 以一般消費者模式至指定門市進行測試 4. 執行測試過程不可暴露神秘客身份 5. 如果有需要，測試過程可能需拍照、錄音(需自備手機、或其他拍照/錄音工具)，或錄影(公司提供) 6. 測試完成後填寫測試心得回饋、', 100, 600, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_羽界創研企業社', '羽界創研企業社', '急徵！在家工作|能聊、能唱、能逗樂的靈魂畫手 聲播主', '台北市中正區', '2026-09-05', 'https://www.104.com.tw/job/901t0', '104', '不露臉也能開啟斜槓人生！ 在家工作的好方向！ ​你是聲音好聽、喜歡聊天，卻不想在鏡頭前露臉的人嗎？ 經紀人 小馬兒正在尋找喜愛互動的你！ 這裡沒有合約束縛，只有最溫馨的陪伴與滿滿的笑聲  ​我們的「三不」承諾： 不簽約：自由選擇，無法律負擔。 不綁時數：你的時間你做主，生活彈性 100%。 不黃色演出：堅持清流，守護主播專業形象。  ​ 為什麼選擇我們？ ​一對一培訓：新手不用怕，專業教學讓你快速', 196, 300, 'remote');
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_晨星國際文化傳媒有限公司', '晨星國際文化傳媒有限公司', '社群小編', '新北市汐止區', '2026-08-13', 'https://www.104.com.tw/job/94tln', '104', '【直播經紀人】工作內容：使用社群招募主播 平台：抖音  1.管理社交媒體平臺，定期更新各種社交媒體平臺上的內容;  2.創建有趣而吸引人的內容，包括圖片、文本和視頻，以吸引更多的用戶關注公司網絡品牌;  3.與其他部門緊密合作，創建和實施網絡營銷活動，以增加品牌知名度;  4.定期監測社交媒體平臺上的數據，以瞭解用戶反應和趨勢;  5.完成其他主管分配的其他相關工作。  本職位是一個充滿挑戰和發展', 40000, 80000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_TUV NORD Taiwan_台灣德國', 'TUV NORD Taiwan_台灣德國北德技術監護顧問股份有限公司', 'Cybersecurity Tech Manager', '台北市大安區', '2026-09-10', 'https://www.104.com.tw/job/8dx0o', '104', '1. 檢查並協助客戶通過各項網路安全認證 2. 協助客戶整合各項標準(見下方：其他條件說明)，取得證照為佳 3. 國際網路功能趨勢與標準宣導 4. 檢驗前後測分析 5. 客戶提問解答  此職務到職後，前期將會由Mentor帶領，從時程安排、了解客戶需求，到陪同客戶端服務，Mentorship後會接受各項專業規範培訓。', NULL, NULL, NULL);
