INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('3443', '學力創意科技股份有限公司', 'Python工程師(Web/APP/IoT開發)', '台北市大安區', '2026-05-19', 'https://www.104.com.tw/job/8u9za', '104', '-Python 監控與維運系統開發 -熟悉Python編程語言 -設計編寫API -系統維運 -技術文件撰寫 -熟悉AWS  【職務條件】 -具有 Git 版本控制相關知識 -熟悉 Linux 基本常見指令 -可獨立或與團隊合作，工作態度積極、負責，能配合公司規定  【程式語言條件】 -需瞭解：Django、Python、PHP、RESTful API -需熟悉資料庫：MongoDB、MySQL', NULL, NULL, NULL);
