INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_映像網路多媒體企業社', '映像網路多媒體企業社', '網路直播平台互動員『新北地區』', '新北市新莊區', '2026-09-06', 'https://www.104.com.tw/job/7azsu', '104', '✨..新世代在家的工作好職  網路時代的蓬勃發展，視訊直播成為時下的工作賺錢好機會， 我們的主播工作主要是在家透過視訊經由直播網站平台與用戶進行交流對談， 與網路上的會員互動，不需要直接接觸，安全性高。   ⧉…具電腦設備筆電、桌電或手機，即可在家輕鬆自由開播✔。 ⧉…在新世代之下...我們在家工作也是相對安全。   ⭐休假⭐：每月自由排班、彈性自由劃假。   ✌具備特質✌：積極有耐心、觀念新穎不', 30000, 60000, 'remote');
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('6531', '微碧愛普科技有限公司', 'Sales Representative 軟體銷售業務專員 (桃園區)', '桃園市桃園區', '2026-09-10', 'https://www.104.com.tw/job/93acv', '104', '【工作地點】 1. 業務範圍包括桃園/新竹/苗栗地區業務 2. 不定期出差支援雙北地區 3. 每月一次總公司會議／每季一次季度會議  【工作內容】 1. 潛在客戶開發（前往拜訪、產品介紹、推廣簽約） 2. 客戶需求分析（瞭解餐飲用戶店內流程，給予方案建議） 3. 系統開通裝機（前往店內裝設硬體、協助軟體開通） 4. 用戶教育訓練（協助用戶熟悉系統基本操作流程） 5. 回報總部近況（自我工作管理並定', 37000, 80000, NULL);
