INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('5213', '亞昕交通有限公司', '工作開特斯拉/機場接送司機/多元化計程車司機/北北基桃居住地安排車輛', '台北市中正區', '2026-09-10', 'https://www.104.com.tw/job/8ub6f', '104', '1.駕駛進口小客車接送乘客 2.職業駕照可機場接送，登記證可市區短程接送 3.不用自備車輛，都是開公司車，不用貸款，免押金，免保證人 4.協助貴賓上下車、提行李，客氣有禮貌穿著不隨便 5.時間自由，營業額拆帳方式計算租金，上線完成最低任務即可 6.多元計程車(完成任務80000，保障抽成45000，超過最低營業額80000後再對拆 公司派單業績1-25萬/月因上線時數而異) 7.合法租賃車(機場接', 1, 200000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('2331', '精英人力資源股份有限公司', '【Nespresso咖啡機_長期專櫃FT_信義Dream Plaza】D23  有興趣私@pge2147h', '台北市信義區', '2026-09-02', 'https://www.104.com.tw/job/85kfc', '104', '【Nespresso咖啡機_長期專櫃FT_信義Dream Plaza】D23 有興趣私@pge2147h ✔在穩健薪資結構上，業績獎金無上限，挑戰高薪不是夢。 ✔提供優秀薪資結構、完整教育訓練、人性化管理..等，名額有限，歡迎您的加入。  【工作內容】- 推廣品牌知名度- 商品銷售與櫃位陳列- 顧客接待、服務與關係維護- 銷售管理及庫存管理 【工作地點】信義Dream Plaza，台北市信義區松高', 33500, 50000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_藝珂人事顧問股份有限公司', '藝珂人事顧問股份有限公司', '【美商酷澎】Associate, Price Sharpness Inspection_財務分析專員 #全遠端_OCS331', '台北市信義區', '2026-09-11', 'https://www.104.com.tw/job/8owd9', '104', '財務規劃與分析是企業財務部門中的一個非常重要的職能，主要負責的內容包括： 預算編制（Budgeting）/預測（Forecasting）/財務報告與分析（Financial Reporting & Analysis）/協助高層做出商業決策（Decision Support） 簡單說，FP&A 就是幫助公司了解現在的財務狀況、預測未來、並提供數據支持管理層做決策的團隊。  1. 依照團隊作業流程檢查', 35000, 35000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_北易大工業有限公司', '北易大工業有限公司', '金屬架構加工安裝團隊', '新北市泰山區', '2026-09-07', 'https://www.104.com.tw/job/8lwly', '104', '合作對象：專業施工團隊 工程類別：營建、裝修、金屬製品安裝 合作模式：依專案需求洽談，長期合作優先  ✅ 營建、裝修相關產品製作與安裝 ✅ 依據設計圖進行精密製作與施工 ✅ 熟悉建築金屬製品（不鏽鋼、鋁、鍍鈦板等） ✅ 具備基本識表、識圖、識材、識製程能力 ✅ 協助現場施工、安裝與品質檢驗 ✅ 其他主管交辦事項   其他事宜可面議！', 5000, 12000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_元聖智能系統科技有限公司', '元聖智能系統科技有限公司', '業務代表', '桃園市蘆竹區', '2026-09-08', 'https://www.104.com.tw/job/8xx4m', '104', '【工作內容】  1. 開發潛在客戶及渠道，拓展自動化設備及系統整合相關商機 2. 維護既有客戶關係，深耕長期合作機會 3. 陪同拜訪客戶，進行需求訪談與專案推進 4. 協助報價製作、合約條件溝通、訂單追蹤及應收款項管理 5. 彙整客戶需求，與專案工程、及內部團隊進行跨部門協調 6. 協助專案前期規劃與商務提案 7. 配合參與國內外展會、市場開發及品牌推廣活動 8. 完成總經理交辦事項  【工作技能', 55000, 9999999, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_美商女力股份有限公司台灣分公司', '美商女力股份有限公司台灣分公司', '線上體態管理教練（遠端工作）', '台北市大安區', '2026-07-23', 'https://www.104.com.tw/job/8wr6l', '104', '想從實體教練轉為線上體態管理教練嗎？這是你的大好機會！  如果你不喜歡每天10小時都在健身房教課、不喜歡公司把你當做銷售員、不喜歡每月背負業績壓力，並且你希望能在一個能持續成長的環境、透過線上將自己的專業正面影響超過上百位女性，那這工作會是你夢想中的工作，我們是說真的！   Nuli app是專為女性打造的健身app。我們致力於幫助亞洲女性更開心、更健康、更對自己引以為傲！  官網：https:/', 35000, 99998, 'remote');
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_祈邑設計有限公司', '祈邑設計有限公司', '展場3D設計', '新北市板橋區', '2026-09-03', 'https://www.104.com.tw/job/91w9z', '104', '【關於我們】 祈邑設計專注於展覽空間、商業空間與品牌視覺整合設計，服務內容涵蓋前期概念規劃、3D視覺提案、施工圖面整合至現場執行。 我們希望透過清楚的3D模型與圖面表達，將設計概念轉化為可被理解、可被執行的空間方案，協助專案從想法落實到現場。  【你將負責】 ◆ 展覽空間、商業空間之3D建模 ◆ 製作提案用3D圖、空間效果圖與渲染圖 ◆ 協助設計師調整空間比例、動線、展示配置與視覺細節 ◆ 依專案', 2000, 200000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_歐那尼股份有限公司', '歐那尼股份有限公司', '日文專員 (遊戲/電玩/翻譯)【歡迎應屆畢業生】', '新北市板橋區', '2026-09-09', 'https://www.104.com.tw/job/81ek2', '104', '【工作內容】 ◎ 翻譯成人向遊戲(以日翻中為主) 。 ◎ 遊戲文本的潤飾校對。 ◎ 協助營運團隊處裡翻譯相關事宜。 ◎ 完成公司/主管交辦事項。   【基本條件】 ◎對ACG有一定程度的認知與喜愛。 ◎不排斥成人作品的內容。 ◎流暢的中文表達能力。 ◎日文檢定2級或與其同程度之其他日文證照檢定。 ◎需檢附日文自傳。   【加分項目】 ◎喜愛並擅長、精通成人ACG內容的老司機。 ◎擁有翻譯經驗。', 30000, 34000, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_美得儀科技有限公司', '美得儀科技有限公司', '【專案合作】醫療設備個人經銷商／通路合作夥伴（高額獎金制 / 免進公司）(高屏地區)', '新北市土城區', '2026-09-07', 'https://www.104.com.tw/job/93lla', '104', '職務亮點：用既有診所人脈，為自己創造高額第二收入！ 您目前已在醫療產業工作，平常有固定接觸診所或醫師嗎？  美得儀科技有限公司誠徵【醫療設備個人經銷商／通路合作夥伴】。 打破傳統打卡限制，無須進公司、不限居住地區（全台皆可），非常適合藥品、醫材、耗材業務利用既有診所通路，多一項高單價醫療設備產品，輕鬆將資源變現！  業界頂規：專案成交獎金制度 本合作採全獎金制（無底薪），我們提供極具競爭力的實質回', 200000, 9999999, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_良橙有限公司', '良橙有限公司', '中區業務專員 （專責中部，遠端工作）', '台中市中區', '2026-09-06', 'https://www.104.com.tw/job/91kvc', '104', '【工作內容】 1. 負責中部零售、餐飲業務開發，日常平時遠端工作不需進公司。約每兩週定期回新竹總公司參與會議及回報業務狀況 2. 開發潛在客戶及地區通路、拓展市場、完場業績目標。初期會提供客戶名單及實地教育訓練協助開發 3. 新、舊客戶拜訪，了解客戶需求並推廣商品、提供報價、提供商品教育訓練及售後服務並與客戶建立良好關係 4. 參與地區超市、餐廳或社團機構之美食試吃活動，協助推廣商品及商品知識 5', NULL, NULL, 'remote');
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_岳凌科技有限公司', '岳凌科技有限公司', '語音廳主播｜不露臉直播語音｜綠色平台', '台中市北屯區', '2026-09-09', 'https://www.104.com.tw/job/91dvi', '104', '你有沒有想過—— 如果只靠聲音就能賺錢，生活會不會輕鬆很多？  現在，真的可以。 不用露臉、不用開鏡頭、不需要會才藝， 只要你喜歡聊天、喜歡陪伴、願意開口說話， 就有機會靠聲音打造屬於自己的斜槓收入  我們正在招募【語音廳主播】！  不管你是： ·深夜療癒系 ·愛聊天的氣氛王 ·幹話連發型 ·撒嬌感、低音炮、魔性笑聲 ·喜歡唱歌、分享生活、談感情  只要你願意開麥，就有人願意聽你說話。  【聲播工', 500, 9999999, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_岳凌科技有限公司', '岳凌科技有限公司', '聲播主招募｜無經驗可｜兼職首選', '台北市信義區', '2026-09-09', 'https://www.104.com.tw/job/91av3', '104', '不露臉也能開直播！聲音主播招募中  喜歡唱歌、聊天、陪人互動嗎？ 現在只要用聲音就能直播，不用露臉，也不用有經驗。  你可以做什麼？ 唱歌、聊天、互動、陪伴粉絲。 時間自由安排，想兼職也很適合。  適合大學生、上班族、寶媽、想增加收入的人。  需要什麼條件？ 有手機就可以。 如果你個性開朗、願意聊天、有熱忱，就很適合加入。  收入福利 禮物分潤 35%～60% 依業績級距提供保底薪酬 另有業績獎金', 500, 9999999, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_台福綜合工業有限公司', '台福綜合工業有限公司', '銷售專員【大台北地區】', '新北市樹林區', '2026-09-08', 'https://www.104.com.tw/job/92vjh', '104', '【工作內容】   1. 開發潛在客戶，拓展市場，以達成業績目標。  2. 定期拜訪經銷客戶，維繫穩定客戶關係。  3. 負責業務接洽及訂單處理。  4. 負責產品報價及產品展示，並處理帳款回收相關事宜。  5. 負責業務推展，傳達及說明公司各項業務重大訊息、活動及產品。  6. 進行商品行銷，產品特色分析介紹，並提供客戶產品購買的建議。  7. 提供售後服務，處理客戶端之問題，給予完善的處理。', 40000, 150000, NULL);
