INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_日伸交通事業有限公司', '日伸交通事業有限公司', '【短期接送司機駕駛｜桃園‧新竹｜公司配車｜時薪220元｜短期3個月】', '桃園市大園區', '2026-09-11', 'https://www.104.com.tw/job/8wzha', '104', '請注意104「聊聊」訊息，我們將透過「聊聊」與您進行初步對談與了解。  我們認為，求職與徵才都是非常重要，且需要雙方認真看待的過程。 正式安排面談前，會先透過線上對談互相了解工作內容、合作模式與彼此期待，期待找到真正適合合作的工作夥伴。  －－－  有些道路，注定需要有人先走出來。 我們是全台第一家達到最高環保標準的交通業者， 也是積極推動多元共融的駕駛團隊。  我們相信，駕駛不只是開車， 更是一', 220, 220, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_資旅軟體開發有限公司', '資旅軟體開發有限公司', 'Angular前端工程師', '台北市信義區', '2026-08-13', 'https://www.104.com.tw/job/94fp9', '104', '【工作內容】 1. 負責電子商務網站前端功能開發與維護，打造流暢且高品質的使用者體驗。 2. 使用 Angular 與 SAP Spartacus 開發、客製化及維護企業級電商平台。 3. 與後端工程師、產品經理、UI/UX 設計師及 QA 團隊密切合作，完成系統功能開發與整合。 4. 串接 RESTful API，實現前後端整合及資料交換。 5. 持續優化網站效能、可維護性及程式碼品質，並協助問', NULL, NULL, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_英屬維京群島商禾寶醫療器材股份有限公司台', '英屬維京群島商禾寶醫療器材股份有限公司台灣分公司', '北/中/南區-醫療耗材標案業務/主管-AH', '台北市內湖區', '2026-09-07', 'https://www.104.com.tw/job/91w7o', '104', '**職稱與薪資依照相關經驗核定，104寫的只是最低薪資，不代表實際薪資核定狀況**  **此業務職務不需跟刀，不需進開刀房，不需等著醫生配合門診時間上下班，不需日夜on call怕漏接電話，不須搬運醫療設備，不用搬著器材從A院跑到B院，不需舉辦學術研討會或是舉辦行銷宣講推銷，走標案採購不須配合醫院繁雜提藥程序，上下班時間有彈性且不需假日加班  對初次想加入醫療產業的你，或是在醫藥業務的繁忙中已經感', NULL, NULL, NULL);
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_崴叡有限公司', '崴叡有限公司', '後端工程師 - Java Engineer(遠端工作)', '新竹市', '2026-08-21', 'https://www.104.com.tw/job/8ge0v', '104', '■ 工作內容   □  分析並設計系統與 API 服務   □  撰寫單元測試、整合測試確保功能正確   □  設計並撰寫分佈式運算服務   □  公開 Review 同事的程式   □  自動化部署與維護   □  對現有設計提出改善意見  ■ 必要條件   □  熟悉 Java 基本語法   □  有單元測試基礎   □  懂基本 SQL 語法   □  使用過 Spring 框架   □', NULL, NULL, 'remote');
INSERT INTO jobs (stock_id, company_name, title, location, date_posted, job_url, source, description, salary_min, salary_max, job_type) VALUES ('ext_岳凌科技有限公司', '岳凌科技有限公司', '無需露臉｜彈性兼職語音主播／聲播主｜無經驗可培訓', '台北市大安區', '2026-09-09', 'https://www.104.com.tw/job/8zi3y', '104', '【無需露臉｜彈性排班】語音互動聲播主／聊天陪伴主持  你喜歡聊天、聲音有親和力，或想找一份彈性斜槓收入嗎？ 這份工作不需要露臉、不需要直播設備，只要透過語音平台與用戶互動聊天、分享生活，經營屬於自己的聲音風格與粉絲關係。  我們不看學歷、不看經驗，更重視你是否願意開口聊天、穩定經營。  工作內容  ・透過語音平台與用戶即時互動、聊天陪伴 ・分享日常、情感交流、話題引導或簡單才藝發揮 ・經營個人聲音', 500, 9999999, NULL);
